window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-8132b4e23057509d"]={"versions": [{"id": "FIG-8132b4e23057509d", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> AUTOSAR M2-Metamodell-Klassendiagramm (UML 2.0 Profil) aus der Spezifikation <code>AUTOSAR_TPS_SystemTemplate</code> (Kapitel Transport Layer).\n</li><li><strong>Funktionale Einordnung:</strong> Definiert die abstrakte Systembeschreibung zur Konfiguration des J1939 Transport Protocol Stacks (<code>J1939Tp</code>) innerhalb des AUTOSAR Classic Com-Stacks. Das Metamodell beschreibt die Segmentierung, Reassemblierung und das Flow-Control-Management für Parameter Groups (PGs) mit Nutzdatenlängen &gt; 8 Byte gemäß SAE J1939-21 (BAM und Point-to-Point RTS/CTS) sowie den Übergang zu CAN-Frames (<code>NPdu</code>) und Oberschicht-Paketen (<code>IPdu</code>/PduR).\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Vererbungshierarchien &amp; Basisklassen</h5>\n<ul class=\"fig-list\"><li><strong><code>TpConfig</code></strong> (abstrakt, spezialisiert <code>FibexElement</code>): Generische Basisklasse für transportspezifische Konfigurationen im System Template.\n</li><li><strong><code>J1939TpConfig</code></strong> (spezialisiert <code>TpConfig</code>): Wurzelaggregat für alle J1939-TP-Artefakte eines Netzwerks.\n</li><li><strong><code>TpConnection</code></strong> (abstrakt): Basisklasse für Transportverbindungen.\n</li><li><strong><code>J1939TpConnection</code></strong> (spezialisiert <code>TpConnection</code>): Konkrete J1939-Transportverbindung.\n</li><li><strong><code>Pdu</code></strong> (abstrakt): Basisklasse für <code>IPdu</code> (Interaktionsschicht / COM) und <code>NPdu</code> (Netzwerkschicht / CAN Interface).\n</li><li><strong><code>J1939TpNode</code></strong>, <strong><code>TpAddress</code></strong>, <strong><code>PhysicalChannel</code></strong>, <strong><code>CommunicationConnector</code></strong>: Spezialisieren <code>Identifiable</code> (besitzen <code>shortName</code>, UUID etc.).\n</li><li><strong><code>EcuInstance</code></strong>: Spezialisiert <code>FibexElement</code>.\n</li></ul>\n<h5 class=\"fig-section-h5\">Entitäten &amp; Attribute</h5>\n<ul class=\"fig-list\"><li><strong><code>J1939TpConnection</code></strong>:\n<ul class=\"fig-list\"><li><code>broadcast :Boolean</code>: Unterscheidung zwischen Broadcast Announce Message (BAM, <code>true</code>) und Peer-to-Peer RTS/CTS (<code>false</code>).\n</li><li><code>bufferRatio :PositiveInteger [0..1]</code>: Pufferallokationsfaktor für Empfangsressourcen.\n</li><li><code>cancellation :Boolean [0..1]</code>: Unterstützung für Verbindungsabbruch (Connection Abort).\n</li><li><code>dynamicBs :Boolean [0..1]</code>: Dynamische Aushandlung der Blockgröße (Block Size).\n</li><li><code>maxBs :PositiveInteger [0..1]</code>: Maximale Blockgröße (Anzahl Frames vor nächstem CTS).\n</li><li><code>maxExpBs :PositiveInteger [0..1]</code>: Maximaler Blockgrößen-Exponent.\n</li><li><code>retry :Boolean [0..1]</code>: Aktivierung von Retransmissions bei Übertragungsfehlern.\n</li></ul>\n</li><li><strong><code>TpAddress</code></strong>:\n<ul class=\"fig-list\"><li><code>tpAddress :Integer</code>: 8-Bit J1939-Knotenadresse (0..253 bzw. 255 für Global/Broadcast).\n</li></ul>\n</li><li><strong><code>J1939TpPg</code></strong>:\n<ul class=\"fig-list\"><li><code>pgn :Integer [0..1]</code>: Parameter Group Number (18-Bit Identifier nach SAE J1939).\n</li><li><code>requestable :Boolean [0..1]</code>: Kennzeichnet, ob die PG mittels PGN 59904 (Request PGN) angefragt werden darf.\n</li></ul>\n</li><li><strong><code>CommunicationConnector</code></strong>:\n<ul class=\"fig-list\"><li><code>pncGatewayType :PncGatewayTypeEnum [0..1]</code>: Gateway-Verhalten für Partial Network Clusters.\n</li></ul>\n</li><li><strong><code>EcuInstance</code></strong>:\n<ul class=\"fig-list\"><li>Enthält Timing-Parameter (<code>comConfigurationTxTimeBase</code>, <code>comConfigurationRxTimeBase</code>, <code>pnResetTime</code> etc.) sowie Feature-Flags (<code>sleepModeSupported</code>, <code>wakeUpOverBusSupported</code>).\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Assoziationen, Kompositionen &amp; Kardinalitäten</h5>\n<ul class=\"fig-list\"><li><strong><code>J1939TpConfig</code></strong>:\n<ul class=\"fig-list\"><li>Komponiert <code>+tpConnection [1..*]</code> (<code>J1939TpConnection</code>) mit Stereotyp <code>«atpVariation»</code> (<code>vh.latestBindingTime = postBuild</code>).\n</li><li>Komponiert <code>+tpNode [1..*]</code> (<code>J1939TpNode</code>) mit <code>«atpVariation»</code> (<code>vh.latestBindingTime = postBuild</code>).\n</li><li>Komponiert <code>+tpAddress [1..*]</code> (<code>TpAddress</code>) mit <code>«atpVariation»</code> (<code>vh.latestBindingTime = postBuild</code>).\n</li></ul>\n</li><li><strong><code>J1939TpConnection</code></strong>:\n<ul class=\"fig-list\"><li>Komponiert <code>+tpPg [0..*]</code> (<code>J1939TpPg</code>).\n</li><li>Referenziert Sender/Empfänger: <code>+transmitter [0..1]</code> und <code>+receiver [0..*]</code> auf <code>J1939TpNode</code>.\n</li><li>Referenziert Protokoll-PDUs: <code>+dataPdu [1]</code> (TP.DT Datenpakete) und <code>+flowControlPdu [1..2]</code> (TP.CM Verbindungssteuerpakete: RTS, CTS, EndOfMsgACK, ConnAbort, BAM) auf <code>NPdu</code>.\n</li></ul>\n</li><li><strong><code>J1939TpNode</code></strong>:\n<ul class=\"fig-list\"><li>Referenziert <code>+tpAddress [0..1]</code> auf <code>TpAddress</code>.\n</li><li>Referenziert <code>+connector [0..1]</code> auf <code>CommunicationConnector</code> (bindet den logischen TP-Knoten an die physische ECU-Schnittstelle).\n</li></ul>\n</li><li><strong><code>J1939TpPg</code></strong>:\n<ul class=\"fig-list\"><li>Referenziert <code>+sdu [0..*]</code> auf <code>IPdu</code> (Payload-Austausch mit PduR / COM).\n</li><li>Referenziert <code>+directPdu [0..1]</code> auf <code>NPdu</code> (Direktübertragung für PGs ≤ 8 Bytes ohne Transportprotokoll-Overhead).\n</li></ul>\n</li><li><strong>Topologische Einbindung</strong>:\n<ul class=\"fig-list\"><li><code>EcuInstance</code> komponiert <code>+connector [*]</code> (<code>CommunicationConnector</code>).\n</li><li><code>PhysicalChannel</code> assoziiert <code>+commConnector [0..*]</code> mit Stereotyp <code>«atpVariation»</code>.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Metamodell definiert die statische Parametrierung für zwei primäre Übertragungspfade:</p>\n<ol class=\"fig-list\"><li><strong>Broadcast Announce Message (BAM) Pfad (<code>broadcast == true</code>):</strong>\n<ul class=\"fig-list\"><li><strong>Trigger:</strong> SDU-Sendeanforderung über PduR an <code>J1939TpPg</code> mit Datenlänge &gt; 8 Byte.\n</li><li><strong>Ablauf:</strong> \n<ol class=\"fig-list\"><li>Sender (<code>transmitter</code>) emittiert TP.CM_BAM über <code>flowControlPdu</code> an die globale Broadcast-Adresse (0xFF).\n</li><li>Sequentielles Senden der Payload-Segmente über <code>dataPdu</code> (TP.DT, 1 Byte Sequence Number + 7 Bytes Payload).\n</li><li>Kein Flow-Control oder Handshake; Einhaltung des Mindestzeitabstands (50 ms bis 200 ms).\n</li><li>Alle zugeordneten <code>receiver [0..*]</code> reassemblieren paketweise.\n</li></ol>\n</li></ul>\n</li><li><strong>Point-to-Point Connection Mode (RTS/CTS) Pfad (<code>broadcast == false</code>):</strong>\n<ul class=\"fig-list\"><li><strong>Trigger:</strong> Sendeanforderung für dedizierte Zieladresse (<code>receiver [1]</code>).\n</li><li><strong>Ablauf:</strong>\n<ol class=\"fig-list\"><li><code>transmitter</code> sendet TP.CM_RTS via <code>flowControlPdu</code>.\n</li><li><code>receiver</code> prüft Puffer (<code>bufferRatio</code>) und antwortet mit TP.CM_CTS via <code>flowControlPdu</code> (vorgegebene Blockgröße via <code>maxBs</code>/<code>dynamicBs</code>).\n</li><li><code>transmitter</code> überträgt bis zu N Datenpakete via <code>dataPdu</code>.\n</li><li>Nach Blockabschluss: Receiver sendet nächstes CTS oder TP.CM_EndOfMsgACK.\n</li><li>Bei Fehler oder Pufferüberlauf: Abbruch über TP.CM_ConnAbort (sofern <code>cancellation == true</code>).\n</li></ol>\n</li></ul>\n</li><li><strong>Direktübertragungspfad (<code>directPdu [0..1]</code> konfiguriert):</strong>\n<ul class=\"fig-list\"><li>Ist die Nutzdatenlänge ≤ 8 Byte, wird das J1939-TP umgangen; der Frame wird ohne Segmentierungs-Header direkt über die referenzierte <code>NPdu</code> an das <code>CanIf</code> übergeben.\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>ECUC-Ableitung (TPS_SYST_01147):</strong> Der System Extractor transformiert diese Topologie direkt in die Konfigurationsparameter des BSW-Moduls <code>J1939Tp</code> (gemäß <code>AUTOSAR_SWS_J1939TransportProtocol</code>):\n<ul class=\"fig-list\"><li><code>J1939TpConnection</code> mappt auf <code>J1939TpChannel</code> (Tx/Rx Channel Pairs).\n</li><li><code>dataPdu</code> und <code>flowControlPdu</code> korrespondieren mit <code>J1939TpPduPool</code> bzw. <code>CanIfTxPduCfg</code> / <code>CanIfRxPduCfg</code>.\n</li><li><code>sdu</code> mappt auf <code>J1939TpTxNSdu</code> / <code>J1939TpRxNSdu</code> und bindet an Routingpfade des <code>PduR</code>.\n</li></ul>\n</li><li><strong>Post-Build-Bindung (<code>vh.latestBindingTime = postBuild</code>):</strong>\n<ul class=\"fig-list\"><li>Die Kompositionen für <code>tpConnection</code>, <code>tpNode</code> und <code>tpAddress</code> tragen das Tag <code>postBuild</code>.\n</li><li>Im BSW-Code müssen Routing-Tabellen, Adresszuweisungen und PDU-IDs tabellenbasiert über Initialisierungsstrukturen (<code>J1939Tp_ConfigType</code>) realisiert werden, um Varianten im Post-Build-Flash ohne Neukompilierung austauschen zu können.\n</li></ul>\n</li><li><strong>Treiber- und Pufferallokation:</strong>\n<ul class=\"fig-list\"><li>Entwickler müssen bei gesetztem <code>dynamicBs = true</code> und variierendem <code>bufferRatio</code> dynamische Tx/Rx-Puffer im <code>J1939Tp</code> dimensionieren, um Deadlocks bei blockierenden CTS-Zuständen im Multichannel-Betrieb zu verhindern.\n</li><li>Das Vorhandensein von <code>directPdu</code> erzwingt im <code>PduR</code> und <code>J1939Tp</code> eine Laufzeit-Längenprüfung: Pakete ≤ 8 Bytes müssen auf den direkten CAN-Treiberpfad geroutet werden, um Buslast durch TP-Control-Frames zu minimieren.\n</li></ul>\n</li></ul>"}, {"id": "FIG-0e020b2804484a6e", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> AUTOSAR M2-Metamodell-Klassendiagramm (UML 2.0 Profil) aus der Spezifikation <code>AUTOSAR_TPS_SystemTemplate</code> (Kapitel Transport Layer).\n</li><li><strong>Funktionale Einordnung:</strong> Definiert die abstrakte Systembeschreibung zur Konfiguration des J1939 Transport Protocol Stacks (<code>J1939Tp</code>) innerhalb des AUTOSAR Classic Com-Stacks. Das Metamodell beschreibt die Segmentierung, Reassemblierung und das Flow-Control-Management für Parameter Groups (PGs) mit Nutzdatenlängen &gt; 8 Byte gemäß SAE J1939-21 (BAM und Point-to-Point RTS/CTS) sowie den Übergang zu CAN-Frames (<code>NPdu</code>) und Oberschicht-Paketen (<code>IPdu</code>/PduR).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Vererbungshierarchien &amp; Basisklassen</h5>\n<ul class=\"fig-list\"><li><strong><code>TpConfig</code></strong> (abstrakt, spezialisiert <code>FibexElement</code>): Generische Basisklasse für transportspezifische Konfigurationen im System Template.\n</li><li><strong><code>J1939TpConfig</code></strong> (spezialisiert <code>TpConfig</code>): Wurzelaggregat für alle J1939-TP-Artefakte eines Netzwerks.\n</li><li><strong><code>TpConnection</code></strong> (abstrakt): Basisklasse für Transportverbindungen.\n</li><li><strong><code>J1939TpConnection</code></strong> (spezialisiert <code>TpConnection</code>): Konkrete J1939-Transportverbindung.\n</li><li><strong><code>Pdu</code></strong> (abstrakt): Basisklasse für <code>IPdu</code> (Interaktionsschicht / COM) und <code>NPdu</code> (Netzwerkschicht / CAN Interface).\n</li><li><strong><code>J1939TpNode</code></strong>, <strong><code>TpAddress</code></strong>, <strong><code>PhysicalChannel</code></strong>, <strong><code>CommunicationConnector</code></strong>: Spezialisieren <code>Identifiable</code> (besitzen <code>shortName</code>, UUID etc.).\n</li><li><strong><code>EcuInstance</code></strong>: Spezialisiert <code>FibexElement</code>.\n</li></ul>\n<h5 class=\"fig-section-h5\">Entitäten &amp; Attribute</h5>\n<ul class=\"fig-list\"><li><strong><code>J1939TpConnection</code></strong>:\n<ul class=\"fig-list\"><li><code>broadcast: Boolean</code>: Unterscheidung zwischen Broadcast Announce Message (BAM, <code>true</code>) und Peer-to-Peer RTS/CTS (<code>false</code>).\n</li><li><code>bufferRatio: PositiveInteger [0..1]</code>: Pufferallokationsfaktor für Empfangsressourcen.\n</li><li><code>cancellation: Boolean [0..1]</code>: Unterstützung für Verbindungsabbruch (Connection Abort).\n</li><li><code>dynamicBs: Boolean [0..1]</code>: Dynamische Aushandlung der Blockgröße (Block Size).\n</li><li><code>maxBs: PositiveInteger [0..1]</code>: Maximale Blockgröße (Anzahl Frames vor nächstem CTS).\n</li><li><code>maxExpBs: PositiveInteger [0..1]</code>: Maximaler Blockgrößen-Exponent.\n</li><li><code>retry: Boolean [0..1]</code>: Aktivierung von Retransmissions bei Übertragungsfehlern.\n</li></ul>\n</li><li><strong><code>TpAddress</code></strong>:\n<ul class=\"fig-list\"><li><code>tpAddress: Integer</code>: 8-Bit J1939-Knotenadresse (0..253 bzw. 255 für Global/Broadcast).\n</li></ul>\n</li><li><strong><code>J1939TpPg</code></strong>:\n<ul class=\"fig-list\"><li><code>pgn: Integer [0..1]</code>: Parameter Group Number (18-Bit Identifier nach SAE J1939).\n</li><li><code>requestable: Boolean [0..1]</code>: Kennzeichnet, ob die PG mittels PGN 59904 (Request PGN) angefragt werden darf.\n</li></ul>\n</li><li><strong><code>CommunicationConnector</code></strong>:\n<ul class=\"fig-list\"><li><code>pncGatewayType: PncGatewayTypeEnum [0..1]</code>: Gateway-Verhalten für Partial Network Clusters.\n</li></ul>\n</li><li><strong><code>EcuInstance</code></strong>:\n<ul class=\"fig-list\"><li>Timing-Parameter (<code>comConfigurationTxTimeBase</code>, <code>comConfigurationRxTimeBase</code>, <code>comConfigurationGwTimeBase</code>, <code>pncPrepareSleepTimer</code>, <code>pnResetTime</code>), Routing-/Netzwerkparameter (<code>comEnableMDTForCyclicTransmission</code>, <code>diagnosticAddress</code>, <code>ethSwitchPortGroupDerivation</code>, <code>v2xSupported</code>) sowie Status-Flags (<code>sleepModeSupported</code>, <code>wakeUpOverBusSupported</code>).\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Assoziationen, Kompositionen &amp; Kardinalitäten</h5>\n<ul class=\"fig-list\"><li><strong><code>J1939TpConfig</code></strong>:\n<ul class=\"fig-list\"><li>Komponiert <code>+tpConnection 1..*</code> (<code>J1939TpConnection</code>) mit Stereotyp <code>«atpVariation»</code>.\n</li><li>Komponiert <code>+tpNode 1..*</code> (<code>J1939TpNode</code>) mit Stereotyp <code>«atpVariation»</code>.\n</li><li>Komponiert <code>+tpAddress 1..*</code> (<code>TpAddress</code>) mit Stereotyp <code>«atpVariation»</code>.\n</li></ul>\n</li><li><strong><code>J1939TpConnection</code></strong>:\n<ul class=\"fig-list\"><li>Komponiert <code>+tpPg 0..*</code> (<code>J1939TpPg</code>).\n</li><li>Referenziert Sender/Empfänger: <code>+transmitter 0..1</code> und <code>+receiver 0..*</code> auf <code>J1939TpNode</code>.\n</li><li>Referenziert Protokoll-PDUs auf <code>NPdu</code>: <code>+flowControlPdu 1..2</code> und <code>+dataPdu 1</code>.\n</li></ul>\n</li><li><strong><code>J1939TpPg</code></strong>:\n<ul class=\"fig-list\"><li>Referenziert <code>+sdu 0..*</code> (<code>IPdu</code>) und <code>+directPdu 0..1</code> (<code>NPdu</code>).\n</li></ul>\n</li><li><strong><code>J1939TpNode</code></strong>:\n<ul class=\"fig-list\"><li>Referenziert Adressen und Hardwareanbindung: <code>+tpAddress 0..1</code> (<code>TpAddress</code>) und <code>+connector 0..1</code> (<code>CommunicationConnector</code>).\n</li></ul>\n</li><li><strong><code>PhysicalChannel</code></strong>:\n<ul class=\"fig-list\"><li>Komponiert <code>+commConnector 0..*</code> (<code>CommunicationConnector</code>) mit Stereotyp <code>«atpVariation»</code>.\n</li><li>Reflexive Assoziation <code>+managedPhysicalChannel 0..*</code> auf <code>PhysicalChannel</code>.\n</li></ul>\n</li><li><strong><code>EcuInstance</code></strong>:\n<ul class=\"fig-list\"><li>Komponiert <code>+connector *</code> (<code>CommunicationConnector</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Metamodell definiert die statische Parametrierung für zwei primäre Übertragungspfade:</p>\n<ol class=\"fig-list\"><li><strong>Broadcast Announce Message (BAM) Pfad (<code>broadcast == true</code>):</strong>\n<ul class=\"fig-list\"><li><strong>Trigger:</strong> SDU-Sendeanforderung über PduR an <code>J1939TpPg</code> mit Datenlänge &gt; 8 Byte.\n</li><li><strong>Ablauf:</strong> \n<ol class=\"fig-list\"><li>Sender (<code>transmitter</code>) emittiert TP.CM_BAM über <code>flowControlPdu</code> an die globale Broadcast-Adresse (0xFF).\n</li><li>Sequentielles Senden der Payload-Segmente über <code>dataPdu</code> (TP.DT, 1 Byte Sequence Number + 7 Bytes Payload).\n</li><li>Kein Flow-Control oder Handshake; Einhaltung des Mindestzeitabstands (50 ms bis 200 ms).\n</li><li>Alle zugeordneten <code>receiver [0..*]</code> reassemblieren paketweise.\n</li></ol>\n</li></ul>\n</li><li><strong>Point-to-Point Connection Mode (RTS/CTS) Pfad (<code>broadcast == false</code>):</strong>\n<ul class=\"fig-list\"><li><strong>Trigger:</strong> Sendeanforderung für dedizierte Zieladresse (<code>receiver [1]</code>).\n</li><li><strong>Ablauf:</strong>\n<ol class=\"fig-list\"><li><code>transmitter</code> sendet TP.CM_RTS via <code>flowControlPdu</code>.\n</li><li><code>receiver</code> prüft Puffer (<code>bufferRatio</code>) und antwortet mit TP.CM_CTS via <code>flowControlPdu</code> (vorgegebene Blockgröße via <code>maxBs</code>/<code>dynamicBs</code>).\n</li><li><code>transmitter</code> überträgt bis zu N Datenpakete via <code>dataPdu</code>.\n</li><li>Nach Blockabschluss: Receiver sendet nächstes CTS oder TP.CM_EndOfMsgACK.\n</li><li>Bei Fehler oder Pufferüberlauf: Abbruch über TP.CM_ConnAbort (sofern <code>cancellation == true</code>).\n</li></ol>\n</li></ul>\n</li><li><strong>Direktübertragungspfad (<code>directPdu [0..1]</code> konfiguriert):</strong>\n<ul class=\"fig-list\"><li>Ist die Nutzdatenlänge ≤ 8 Byte, wird das J1939-TP umgangen; der Frame wird ohne Segmentierungs-Header direkt über die referenzierte <code>NPdu</code> an das <code>CanIf</code> übergeben.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>ECUC-Ableitung (TPS_SYST_01147):</strong> Der System Extractor transformiert diese Topologie direkt in die Konfigurationsparameter des BSW-Moduls <code>J1939Tp</code> (gemäß <code>AUTOSAR_SWS_J1939TransportProtocol</code>):\n<ul class=\"fig-list\"><li><code>J1939TpConnection</code> mappt auf <code>J1939TpChannel</code> (Tx/Rx Channel Pairs).\n</li><li><code>dataPdu</code> und <code>flowControlPdu</code> korrespondieren mit <code>J1939TpPduPool</code> bzw. <code>CanIfTxPduCfg</code> / <code>CanIfRxPduCfg</code>.\n</li><li><code>sdu</code> mappt auf <code>J1939TpTxNSdu</code> / <code>J1939TpRxNSdu</code> und bindet an Routingpfade des <code>PduR</code>.\n</li></ul>\n</li><li><strong>Post-Build-Bindung (<code>vh.latestBindingTime = postBuild</code>):</strong>\n<ul class=\"fig-list\"><li>Die Kompositionen für <code>tpConnection</code>, <code>tpNode</code> und <code>tpAddress</code> tragen das Tag <code>postBuild</code>.\n</li><li>Im BSW-Code müssen Routing-Tabellen, Adresszuweisungen und PDU-IDs tabellenbasiert über Initialisierungsstrukturen (<code>J1939Tp_ConfigType</code>) realisiert werden, um Varianten im Post-Build-Flash ohne Neukompilierung austauschen zu können.\n</li></ul>\n</li><li><strong>Treiber- und Pufferallokation:</strong>\n<ul class=\"fig-list\"><li>Entwickler müssen bei gesetztem <code>dynamicBs = true</code> und variierendem <code>bufferRatio</code> dynamische Tx/Rx-Puffer im <code>J1939Tp</code> dimensionieren, um Deadlocks bei blockierenden CTS-Zuständen im Multichannel-Betrieb zu verhindern.\n</li><li>Das Vorhandensein von <code>directPdu</code> erzwingt im <code>PduR</code> und <code>J1939Tp</code> eine Laufzeit-Längenprüfung: Pakete ≤ 8 Bytes müssen auf den direkten CAN-Treiberpfad geroutet werden, um Buslast durch TP-Control-Frames zu minimieren.\n</li></ul>\n</li></ul>"}, {"id": "FIG-2db868dee23c47f6", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> AUTOSAR M2-Metamodell-Klassendiagramm (UML 2.0 Profil) aus der Spezifikation <code>AUTOSAR_TPS_SystemTemplate</code> (Kapitel Transport Layer).\n</li><li><strong>Funktionale Einordnung:</strong> Definiert die abstrakte Systembeschreibung zur Konfiguration des J1939 Transport Protocol Stacks (<code>J1939Tp</code>) innerhalb des AUTOSAR Classic Com-Stacks. Das Metamodell beschreibt die Segmentierung, Reassemblierung und das Flow-Control-Management für Parameter Groups (PGs) mit Nutzdatenlängen &gt; 8 Byte gemäß SAE J1939-21 (BAM und Point-to-Point RTS/CTS) sowie den Übergang zu CAN-Frames (<code>NPdu</code>) und Oberschicht-Paketen (<code>IPdu</code>/PduR).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Vererbungshierarchien &amp; Basisklassen</h5>\n<ul class=\"fig-list\"><li><strong><code>J1939TpConfig</code></strong> (spezialisiert die im Diagrammkopf referenzierte Superklasse <code>TpConfig</code>): Wurzelaggregat für alle J1939-TP-Artefakte eines Netzwerks.\n</li><li><strong><code>TpConnection</code></strong> (abstrakt): Basisklasse für Transportverbindungen.\n</li><li><strong><code>J1939TpConnection</code></strong> (spezialisiert <code>TpConnection</code>): Konkrete J1939-Transportverbindung.\n</li><li><strong><code>Pdu</code></strong> (abstrakt): Basisklasse für <code>IPdu</code> (Interaktionsschicht / COM) und <code>NPdu</code> (Netzwerkschicht / CAN Interface).\n</li><li><strong><code>J1939TpNode</code></strong>, <strong><code>TpAddress</code></strong>, <strong><code>PhysicalChannel</code></strong>, <strong><code>CommunicationConnector</code></strong>: Spezialisieren <code>Identifiable</code> (besitzen <code>shortName</code>, UUID etc.).\n</li><li><strong><code>EcuInstance</code></strong>: Spezialisiert <code>FibexElement</code>.\n</li></ul>\n<h5 class=\"fig-section-h5\">Entitäten &amp; Attribute</h5>\n<ul class=\"fig-list\"><li><strong><code>J1939TpConnection</code></strong>:\n<ul class=\"fig-list\"><li><code>broadcast: Boolean</code>: Unterscheidung zwischen Broadcast Announce Message (BAM, <code>true</code>) und Peer-to-Peer RTS/CTS (<code>false</code>).\n</li><li><code>bufferRatio: PositiveInteger [0..1]</code>: Pufferallokationsfaktor für Empfangsressourcen.\n</li><li><code>cancellation: Boolean [0..1]</code>: Unterstützung für Verbindungsabbruch (Connection Abort).\n</li><li><code>dynamicBs: Boolean [0..1]</code>: Dynamische Aushandlung der Blockgröße (Block Size).\n</li><li><code>maxBs: PositiveInteger [0..1]</code>: Maximale Blockgröße (Anzahl Frames vor nächstem CTS).\n</li><li><code>maxExpBs: PositiveInteger [0..1]</code>: Maximaler Blockgrößen-Exponent.\n</li><li><code>retry: Boolean [0..1]</code>: Aktivierung von Retransmissions bei Übertragungsfehlern.\n</li></ul>\n</li><li><strong><code>TpAddress</code></strong>:\n<ul class=\"fig-list\"><li><code>tpAddress: Integer</code>: 8-Bit J1939-Knotenadresse (0..253 bzw. 255 für Global/Broadcast).\n</li></ul>\n</li><li><strong><code>J1939TpPg</code></strong>:\n<ul class=\"fig-list\"><li><code>pgn: Integer [0..1]</code>: Parameter Group Number (18-Bit Identifier nach SAE J1939).\n</li><li><code>requestable: Boolean [0..1]</code>: Kennzeichnet, ob die PG mittels PGN 59904 (Request PGN) angefragt werden darf.\n</li></ul>\n</li><li><strong><code>CommunicationConnector</code></strong>:\n<ul class=\"fig-list\"><li><code>createEcuWakeupSource: Boolean [0..1]</code>: Steuerung der automatischen Wakeup-Source-Generierung für das Interface.\n</li><li><code>pncGatewayType: PncGatewayTypeEnum [0..1]</code>: Gateway-Verhalten für Partial Network Clusters.\n</li></ul>\n</li><li><strong><code>EcuInstance</code></strong>:\n<ul class=\"fig-list\"><li>Timing-Parameter (<code>comConfigurationTxTimeBase</code>, <code>comConfigurationRxTimeBase</code>, <code>comConfigurationGwTimeBase</code>, <code>pncPrepareSleepTimer</code>, <code>pnResetTime</code>), Netzwerk- und PNC-Parameter (<code>comEnableMDTForCyclicTransmission</code>, <code>ethSwitchPortGroupDerivation</code>, <code>pncSynchronousWakeup</code>, <code>v2xSupported</code>) sowie Status-Flags (<code>sleepModeSupported</code>, <code>wakeUpOverBusSupported</code>).\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Assoziationen, Kompositionen &amp; Kardinalitäten</h5>\n<ul class=\"fig-list\"><li><strong><code>J1939TpConfig</code></strong>:\n<ul class=\"fig-list\"><li>Komponiert <code>+tpConnection 1..*</code> (<code>J1939TpConnection</code>) mit Stereotyp <code>«atpVariation»</code>.\n</li><li>Komponiert <code>+tpNode 1..*</code> (<code>J1939TpNode</code>) mit Stereotyp <code>«atpVariation»</code>.\n</li><li>Komponiert <code>+tpAddress 1..*</code> (<code>TpAddress</code>) mit Stereotyp <code>«atpVariation»</code>.\n</li></ul>\n</li><li><strong><code>J1939TpConnection</code></strong>:\n<ul class=\"fig-list\"><li>Komponiert <code>+tpPg 0..*</code> (<code>J1939TpPg</code>).\n</li><li>Referenziert Sender/Empfänger: <code>+transmitter 0..1</code> und <code>+receiver 0..*</code> auf <code>J1939TpNode</code>.\n</li><li>Referenziert Protokoll-PDUs auf <code>NPdu</code>: <code>+flowControlPdu 1..2</code> und <code>+dataPdu 1</code>.\n</li></ul>\n</li><li><strong><code>J1939TpPg</code></strong>:\n<ul class=\"fig-list\"><li>Referenziert <code>+sdu 0..*</code> (<code>IPdu</code>) und <code>+directPdu 0..1</code> (<code>NPdu</code>).\n</li></ul>\n</li><li><strong><code>J1939TpNode</code></strong>:\n<ul class=\"fig-list\"><li>Referenziert Adressen und Hardwareanbindung: <code>+tpAddress 0..1</code> (<code>TpAddress</code>) und <code>+connector 0..1</code> (<code>CommunicationConnector</code>).\n</li></ul>\n</li><li><strong><code>PhysicalChannel</code></strong>:\n<ul class=\"fig-list\"><li>Komponiert <code>+commConnector 0..*</code> (<code>CommunicationConnector</code>) mit Stereotyp <code>«atpVariation»</code>.\n</li><li>Reflexive Assoziation <code>+managedPhysicalChannel 0..*</code> auf <code>PhysicalChannel</code>.\n</li></ul>\n</li><li><strong><code>EcuInstance</code></strong>:\n<ul class=\"fig-list\"><li>Komponiert <code>+connector *</code> (<code>CommunicationConnector</code>) mit Stereotyp <code>«atpVariation»</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Metamodell definiert die statische Parametrierung für zwei primäre Übertragungspfade:</p>\n<ol class=\"fig-list\"><li><strong>Broadcast Announce Message (BAM) Pfad (<code>broadcast == true</code>):</strong>\n<ul class=\"fig-list\"><li><strong>Trigger:</strong> SDU-Sendeanforderung über PduR an <code>J1939TpPg</code> mit Datenlänge &gt; 8 Byte.\n</li><li><strong>Ablauf:</strong> \n<ol class=\"fig-list\"><li>Sender (<code>transmitter</code>) emittiert TP.CM_BAM über <code>flowControlPdu</code> an die globale Broadcast-Adresse (0xFF).\n</li><li>Sequentielles Senden der Payload-Segmente über <code>dataPdu</code> (TP.DT, 1 Byte Sequence Number + 7 Bytes Payload).\n</li><li>Kein Flow-Control oder Handshake; Einhaltung des Mindestzeitabstands (50 ms bis 200 ms).\n</li><li>Alle zugeordneten <code>receiver [0..*]</code> reassemblieren paketweise.\n</li></ol>\n</li></ul>\n</li><li><strong>Point-to-Point Connection Mode (RTS/CTS) Pfad (<code>broadcast == false</code>):</strong>\n<ul class=\"fig-list\"><li><strong>Trigger:</strong> Sendeanforderung für dedizierte Zieladresse (<code>receiver [1]</code>).\n</li><li><strong>Ablauf:</strong>\n<ol class=\"fig-list\"><li><code>transmitter</code> sendet TP.CM_RTS via <code>flowControlPdu</code>.\n</li><li><code>receiver</code> prüft Puffer (<code>bufferRatio</code>) und antwortet mit TP.CM_CTS via <code>flowControlPdu</code> (vorgegebene Blockgröße via <code>maxBs</code>/<code>dynamicBs</code>).\n</li><li><code>transmitter</code> überträgt bis zu N Datenpakete via <code>dataPdu</code>.\n</li><li>Nach Blockabschluss: Receiver sendet nächstes CTS oder TP.CM_EndOfMsgACK.\n</li><li>Bei Fehler oder Pufferüberlauf: Abbruch über TP.CM_ConnAbort (sofern <code>cancellation == true</code>).\n</li></ol>\n</li></ul>\n</li><li><strong>Direktübertragungspfad (<code>directPdu [0..1]</code> konfiguriert):</strong>\n<ul class=\"fig-list\"><li>Ist die Nutzdatenlänge ≤ 8 Byte, wird das J1939-TP umgangen; der Frame wird ohne Segmentierungs-Header direkt über die referenzierte <code>NPdu</code> an das <code>CanIf</code> übergeben.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>ECUC-Ableitung (TPS_SYST_01147):</strong> Der System Extractor transformiert diese Topologie direkt in die Konfigurationsparameter des BSW-Moduls <code>J1939Tp</code> (gemäß <code>AUTOSAR_SWS_J1939TransportProtocol</code>):\n<ul class=\"fig-list\"><li><code>J1939TpConnection</code> mappt auf <code>J1939TpChannel</code> (Tx/Rx Channel Pairs).\n</li><li><code>dataPdu</code> und <code>flowControlPdu</code> korrespondieren mit <code>J1939TpPduPool</code> bzw. <code>CanIfTxPduCfg</code> / <code>CanIfRxPduCfg</code>.\n</li><li><code>sdu</code> mappt auf <code>J1939TpTxNSdu</code> / <code>J1939TpRxNSdu</code> und bindet an Routingpfade des <code>PduR</code>.\n</li></ul>\n</li><li><strong>Post-Build-Bindung (<code>vh.latestBindingTime = postBuild</code>):</strong>\n<ul class=\"fig-list\"><li>Die Kompositionen für <code>tpConnection</code>, <code>tpNode</code> und <code>tpAddress</code> tragen das Tag <code>postBuild</code>.\n</li><li>Im BSW-Code müssen Routing-Tabellen, Adresszuweisungen und PDU-IDs tabellenbasiert über Initialisierungsstrukturen (<code>J1939Tp_ConfigType</code>) realisiert werden, um Varianten im Post-Build-Flash ohne Neukompilierung austauschen zu können.\n</li></ul>\n</li><li><strong>Treiber- und Pufferallokation:</strong>\n<ul class=\"fig-list\"><li>Entwickler müssen bei gesetztem <code>dynamicBs = true</code> und variierendem <code>bufferRatio</code> dynamische Tx/Rx-Puffer im <code>J1939Tp</code> dimensionieren, um Deadlocks bei blockierenden CTS-Zuständen im Multichannel-Betrieb zu verhindern.\n</li><li>Das Vorhandensein von <code>directPdu</code> erzwingt im <code>PduR</code> und <code>J1939Tp</code> eine Laufzeit-Längenprüfung: Pakete ≤ 8 Bytes müssen auf den direkten CAN-Treiberpfad geroutet werden, um Buslast durch TP-Control-Frames zu minimieren.\n</li></ul>\n</li></ul>"}, {"id": "FIG-f35d4a7e2f441363", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> AUTOSAR M2-Metamodell-Klassendiagramm (UML 2.0 Profil) aus der Spezifikation <code>AUTOSAR_TPS_SystemTemplate</code> (Kapitel Transport Layer).\n</li><li><strong>Funktionale Einordnung:</strong> Definiert die abstrakte Systembeschreibung zur Konfiguration des J1939 Transport Protocol Stacks (<code>J1939Tp</code>) innerhalb des AUTOSAR Classic Com-Stacks. Das Metamodell beschreibt die Segmentierung, Reassemblierung und das Flow-Control-Management für Parameter Groups (PGs) mit Nutzdatenlängen &gt; 8 Byte gemäß SAE J1939-21 (BAM und Point-to-Point RTS/CTS) sowie den Übergang zu CAN-Frames (<code>NPdu</code>) und Oberschicht-Paketen (<code>IPdu</code>/PduR).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Vererbungshierarchien &amp; Basisklassen</h5>\n<ul class=\"fig-list\"><li><strong><code>J1939TpConfig</code></strong> (spezialisiert die im Diagrammkopf referenzierte Superklasse <code>TpConfig</code>): Wurzelaggregat für alle J1939-TP-Artefakte eines Netzwerks.\n</li><li><strong><code>TpConnection</code></strong> (abstrakt): Basisklasse für Transportverbindungen.\n</li><li><strong><code>J1939TpConnection</code></strong> (spezialisiert <code>TpConnection</code>): Konkrete J1939-Transportverbindung.\n</li><li><strong><code>Pdu</code></strong> (abstrakt): Basisklasse für <code>IPdu</code> (Interaktionsschicht / COM) und <code>NPdu</code> (Netzwerkschicht / CAN Interface).\n</li><li><strong><code>J1939TpNode</code></strong>, <strong><code>TpAddress</code></strong>, <strong><code>PhysicalChannel</code></strong>, <strong><code>CommunicationConnector</code></strong>: Spezialisieren <code>Identifiable</code> (besitzen <code>shortName</code>, UUID etc.).\n</li><li><strong><code>EcuInstance</code></strong>: Spezialisiert <code>FibexElement</code>.\n</li></ul>\n<h5 class=\"fig-section-h5\">Entitäten &amp; Attribute</h5>\n<ul class=\"fig-list\"><li><strong><code>J1939TpConnection</code></strong>:\n<ul class=\"fig-list\"><li><code>broadcast: Boolean</code>: Unterscheidung zwischen Broadcast Announce Message (BAM, <code>true</code>) und Peer-to-Peer RTS/CTS (<code>false</code>).\n</li><li><code>bufferRatio: PositiveInteger [0..1]</code>: Pufferallokationsfaktor für Empfangsressourcen.\n</li><li><code>cancellation: Boolean [0..1]</code>: Unterstützung für Verbindungsabbruch (Connection Abort).\n</li><li><code>dynamicBs: Boolean [0..1]</code>: Dynamische Aushandlung der Blockgröße (Block Size).\n</li><li><code>maxBs: PositiveInteger [0..1]</code>: Maximale Blockgröße (Anzahl Frames vor nächstem CTS).\n</li><li><code>maxExpBs: PositiveInteger [0..1]</code>: Maximaler Blockgrößen-Exponent.\n</li><li><code>retry: Boolean [0..1]</code>: Aktivierung von Retransmissions bei Übertragungsfehlern.\n</li></ul>\n</li><li><strong><code>TpAddress</code></strong>:\n<ul class=\"fig-list\"><li><code>tpAddress: Integer</code>: 8-Bit J1939-Knotenadresse (0..253 bzw. 255 für Global/Broadcast).\n</li></ul>\n</li><li><strong><code>J1939TpPg</code></strong>:\n<ul class=\"fig-list\"><li><code>pgn: Integer [0..1]</code>: Parameter Group Number (18-Bit Identifier nach SAE J1939).\n</li><li><code>requestable: Boolean [0..1]</code>: Kennzeichnet, ob die PG mittels PGN 59904 (Request PGN) angefragt werden darf.\n</li></ul>\n</li><li><strong><code>CommunicationConnector</code></strong>:\n<ul class=\"fig-list\"><li><code>createEcuWakeupSource: Boolean [0..1]</code>: Steuerung der automatischen Wakeup-Source-Generierung für das Interface.\n</li><li><code>dynamicPncToChannelMappingEnabled: Boolean [0..1]</code>: Aktiviert die dynamische Zuordnung von PNCs zu Kommunikationskanälen.\n</li><li><code>pncGatewayType: PncGatewayTypeEnum [0..1]</code>: Gateway-Verhalten für Partial Network Clusters.\n</li></ul>\n</li><li><strong><code>EcuInstance</code></strong>:\n<ul class=\"fig-list\"><li>Timing-Parameter (<code>comConfigurationTxTimeBase</code>, <code>comConfigurationRxTimeBase</code>, <code>comConfigurationGwTimeBase</code>, <code>pncPrepareSleepTimer</code>, <code>pnResetTime</code>), Netzwerk- und PNC-Parameter (<code>comEnableMDTForCyclicTransmission</code>, <code>ethSwitchPortGroupDerivation</code>, <code>pncSynchronousWakeup</code>, <code>v2xSupported</code>) sowie Status-Flags (<code>sleepModeSupported</code>, <code>wakeUpOverBusSupported</code>).\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Assoziationen, Kompositionen &amp; Kardinalitäten</h5>\n<ul class=\"fig-list\"><li><strong><code>J1939TpConfig</code></strong>:\n<ul class=\"fig-list\"><li>Komponiert <code>+tpConnection 1..*</code> (<code>J1939TpConnection</code>) mit Stereotyp <code>«atpVariation»</code>.\n</li><li>Komponiert <code>+tpNode 1..*</code> (<code>J1939TpNode</code>) mit Stereotyp <code>«atpVariation»</code>.\n</li><li>Komponiert <code>+tpAddress 1..*</code> (<code>TpAddress</code>) mit Stereotyp <code>«atpVariation»</code>.\n</li></ul>\n</li><li><strong><code>J1939TpConnection</code></strong>:\n<ul class=\"fig-list\"><li>Komponiert <code>+tpPg 0..*</code> (<code>J1939TpPg</code>).\n</li><li>Referenziert Sender/Empfänger: <code>+transmitter 0..1</code> und <code>+receiver 0..*</code> auf <code>J1939TpNode</code>.\n</li><li>Referenziert Protokoll-PDUs auf <code>NPdu</code>: <code>+flowControlPdu 1..2</code> und <code>+dataPdu 1</code>.\n</li></ul>\n</li><li><strong><code>J1939TpPg</code></strong>:\n<ul class=\"fig-list\"><li>Referenziert <code>+sdu 0..*</code> (<code>IPdu</code>) und <code>+directPdu 0..1</code> (<code>NPdu</code>).\n</li></ul>\n</li><li><strong><code>J1939TpNode</code></strong>:\n<ul class=\"fig-list\"><li>Referenziert Adressen und Hardwareanbindung: <code>+tpAddress 0..1</code> (<code>TpAddress</code>) und <code>+connector 0..1</code> (<code>CommunicationConnector</code>).\n</li></ul>\n</li><li><strong><code>PhysicalChannel</code></strong>:\n<ul class=\"fig-list\"><li>Komponiert <code>+commConnector 0..*</code> (<code>CommunicationConnector</code>) mit Stereotyp <code>«atpVariation»</code>.\n</li><li>Reflexive Assoziation <code>+managedPhysicalChannel 0..*</code> auf <code>PhysicalChannel</code>.\n</li></ul>\n</li><li><strong><code>EcuInstance</code></strong>:\n<ul class=\"fig-list\"><li>Komponiert <code>+connector *</code> (<code>CommunicationConnector</code>) mit Stereotyp <code>«atpVariation»</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Metamodell definiert die statische Parametrierung für zwei primäre Übertragungspfade:</p>\n<ol class=\"fig-list\"><li><strong>Broadcast Announce Message (BAM) Pfad (<code>broadcast == true</code>):</strong>\n<ul class=\"fig-list\"><li><strong>Trigger:</strong> SDU-Sendeanforderung über PduR an <code>J1939TpPg</code> mit Datenlänge &gt; 8 Byte.\n</li><li><strong>Ablauf:</strong> \n<ol class=\"fig-list\"><li>Sender (<code>transmitter</code>) emittiert TP.CM_BAM über <code>flowControlPdu</code> an die globale Broadcast-Adresse (0xFF).\n</li><li>Sequentielles Senden der Payload-Segmente über <code>dataPdu</code> (TP.DT, 1 Byte Sequence Number + 7 Bytes Payload).\n</li><li>Kein Flow-Control oder Handshake; Einhaltung des Mindestzeitabstands (50 ms bis 200 ms).\n</li><li>Alle zugeordneten <code>receiver [0..*]</code> reassemblieren paketweise.\n</li></ol>\n</li></ul>\n</li><li><strong>Point-to-Point Connection Mode (RTS/CTS) Pfad (<code>broadcast == false</code>):</strong>\n<ul class=\"fig-list\"><li><strong>Trigger:</strong> Sendeanforderung für dedizierte Zieladresse (<code>receiver [1]</code>).\n</li><li><strong>Ablauf:</strong>\n<ol class=\"fig-list\"><li><code>transmitter</code> sendet TP.CM_RTS via <code>flowControlPdu</code>.\n</li><li><code>receiver</code> prüft Puffer (<code>bufferRatio</code>) und antwortet mit TP.CM_CTS via <code>flowControlPdu</code> (vorgegebene Blockgröße via <code>maxBs</code>/<code>dynamicBs</code>).\n</li><li><code>transmitter</code> überträgt bis zu N Datenpakete via <code>dataPdu</code>.\n</li><li>Nach Blockabschluss: Receiver sendet nächstes CTS oder TP.CM_EndOfMsgACK.\n</li><li>Bei Fehler oder Pufferüberlauf: Abbruch über TP.CM_ConnAbort (sofern <code>cancellation == true</code>).\n</li></ol>\n</li></ul>\n</li><li><strong>Direktübertragungspfad (<code>directPdu [0..1]</code> konfiguriert):</strong>\n<ul class=\"fig-list\"><li>Ist die Nutzdatenlänge ≤ 8 Byte, wird das J1939-TP umgangen; der Frame wird ohne Segmentierungs-Header direkt über die referenzierte <code>NPdu</code> an das <code>CanIf</code> übergeben.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>ECUC-Ableitung (TPS_SYST_01147):</strong> Der System Extractor transformiert diese Topologie direkt in die Konfigurationsparameter des BSW-Moduls <code>J1939Tp</code> (gemäß <code>AUTOSAR_SWS_J1939TransportProtocol</code>):\n<ul class=\"fig-list\"><li><code>J1939TpConnection</code> mappt auf <code>J1939TpChannel</code> (Tx/Rx Channel Pairs).\n</li><li><code>dataPdu</code> und <code>flowControlPdu</code> korrespondieren mit <code>J1939TpPduPool</code> bzw. <code>CanIfTxPduCfg</code> / <code>CanIfRxPduCfg</code>.\n</li><li><code>sdu</code> mappt auf <code>J1939TpTxNSdu</code> / <code>J1939TpRxNSdu</code> und bindet an Routingpfade des <code>PduR</code>.\n</li></ul>\n</li><li><strong>Post-Build-Bindung (<code>vh.latestBindingTime = postBuild</code>):</strong>\n<ul class=\"fig-list\"><li>Die Kompositionen für <code>tpConnection</code>, <code>tpNode</code> und <code>tpAddress</code> tragen das Tag <code>postBuild</code>.\n</li><li>Im BSW-Code müssen Routing-Tabellen, Adresszuweisungen und PDU-IDs tabellenbasiert über Initialisierungsstrukturen (<code>J1939Tp_ConfigType</code>) realisiert werden, um Varianten im Post-Build-Flash ohne Neukompilierung austauschen zu können.\n</li></ul>\n</li><li><strong>Treiber- und Pufferallokation:</strong>\n<ul class=\"fig-list\"><li>Entwickler müssen bei gesetztem <code>dynamicBs = true</code> und variierendem <code>bufferRatio</code> dynamische Tx/Rx-Puffer im <code>J1939Tp</code> dimensionieren, um Deadlocks bei blockierenden CTS-Zuständen im Multichannel-Betrieb zu verhindern.\n</li><li>Das Vorhandensein von <code>directPdu</code> erzwingt im <code>PduR</code> und <code>J1939Tp</code> eine Laufzeit-Längenprüfung: Pakete ≤ 8 Bytes müssen auf den direkten CAN-Treiberpfad geroutet werden, um Buslast durch TP-Control-Frames zu minimieren.\n</li></ul>\n</li></ul>"}, {"id": "FIG-be9824606273cce4", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> AUTOSAR M2-Metamodell-Klassendiagramm (UML 2.0 Profil) aus der Spezifikation <code>AUTOSAR_TPS_SystemTemplate</code> (Kapitel Transport Layer).\n</li><li><strong>Funktionale Einordnung:</strong> Definiert die abstrakte Systembeschreibung zur Konfiguration des J1939 Transport Protocol Stacks (<code>J1939Tp</code>) innerhalb des AUTOSAR Classic Com-Stacks. Das Metamodell beschreibt die Segmentierung, Reassemblierung und das Flow-Control-Management für Parameter Groups (PGs) mit Nutzdatenlängen &gt; 8 Byte gemäß SAE J1939-21 (BAM und Point-to-Point RTS/CTS) sowie den Übergang zu CAN-Frames (<code>NPdu</code>) und Oberschicht-Paketen (<code>IPdu</code>/PduR).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Vererbungshierarchien &amp; Basisklassen</h5>\n<ul class=\"fig-list\"><li><strong><code>J1939TpConfig</code></strong> (spezialisiert die im Diagrammkopf referenzierte Superklasse <code>TpConfig</code>): Wurzelaggregat für alle J1939-TP-Artefakte eines Netzwerks.\n</li><li><strong><code>TpConnection</code></strong> (abstrakt): Basisklasse für Transportverbindungen.\n</li><li><strong><code>J1939TpConnection</code></strong> (spezialisiert <code>TpConnection</code>): Konkrete J1939-Transportverbindung.\n</li><li><strong><code>Pdu</code></strong> (abstrakt): Basisklasse für <code>IPdu</code> (Interaktionsschicht / COM) und <code>NPdu</code> (Netzwerkschicht / CAN Interface).\n</li><li><strong><code>J1939TpNode</code></strong>, <strong><code>TpAddress</code></strong>, <strong><code>PhysicalChannel</code></strong>, <strong><code>CommunicationConnector</code></strong>: Spezialisieren <code>Identifiable</code> (besitzen <code>shortName</code>, UUID etc.).\n</li><li><strong><code>EcuInstance</code></strong>: Spezialisiert <code>FibexElement</code>.\n</li></ul>\n<h5 class=\"fig-section-h5\">Entitäten &amp; Attribute</h5>\n<ul class=\"fig-list\"><li><strong><code>J1939TpConnection</code></strong>:\n<ul class=\"fig-list\"><li><code>broadcast: Boolean</code>: Unterscheidung zwischen Broadcast Announce Message (BAM, <code>true</code>) und Peer-to-Peer RTS/CTS (<code>false</code>).\n</li><li><code>bufferRatio: PositiveInteger [0..1]</code>: Pufferallokationsfaktor für Empfangsressourcen.\n</li><li><code>cancellation: Boolean [0..1]</code>: Unterstützung für Verbindungsabbruch (Connection Abort).\n</li><li><code>dynamicBs: Boolean [0..1]</code>: Dynamische Aushandlung der Blockgröße (Block Size).\n</li><li><code>maxBs: PositiveInteger [0..1]</code>: Maximale Blockgröße (Anzahl Frames vor nächstem CTS).\n</li><li><code>maxExpBs: PositiveInteger [0..1]</code>: Maximaler Blockgrößen-Exponent.\n</li><li><code>retry: Boolean [0..1]</code>: Aktivierung von Retransmissions bei Übertragungsfehlern.\n</li></ul>\n</li><li><strong><code>TpAddress</code></strong>:\n<ul class=\"fig-list\"><li><code>tpAddress: Integer</code>: 8-Bit J1939-Knotenadresse (0..253 bzw. 255 für Global/Broadcast).\n</li></ul>\n</li><li><strong><code>J1939TpPg</code></strong>:\n<ul class=\"fig-list\"><li><code>pgn: Integer [0..1]</code>: Parameter Group Number (18-Bit Identifier nach SAE J1939).\n</li><li><code>requestable: Boolean [0..1]</code>: Kennzeichnet, ob die PG mittels PGN 59904 (Request PGN) angefragt werden darf.\n</li></ul>\n</li><li><strong><code>CommunicationConnector</code></strong>:\n<ul class=\"fig-list\"><li><code>createEcuWakeupSource: Boolean [0..1]</code>: Steuerung der automatischen Wakeup-Source-Generierung für das Interface.\n</li><li><code>dynamicPncToChannelMappingEnabled: Boolean [0..1]</code>: Aktiviert die dynamische Zuordnung von PNCs zu Kommunikationskanälen.\n</li><li><code>pncFilterArrayMask: PositiveInteger [0..*] {ordered}</code>: Geordnete Bitmaske für PNC-Filterung.\n</li><li><code>pncGatewayType: PncGatewayTypeEnum [0..1]</code>: Gateway-Verhalten für Partial Network Clusters.\n</li></ul>\n</li><li><strong><code>EcuInstance</code></strong>:\n<ul class=\"fig-list\"><li>Timing-Parameter (<code>comConfigurationTxTimeBase</code>, <code>comConfigurationRxTimeBase</code>, <code>comConfigurationGwTimeBase</code>, <code>pncPrepareSleepTimer</code>, <code>pnResetTime</code>), PNC- und Netzwerkparameter (<code>comEnableMDTForCyclicTransmission</code>, <code>ethSwitchPortGroupDerivation</code>, <code>pncNmRequest: Boolean [0..1]</code>, <code>pncSynchronousWakeup</code>, <code>v2xSupported</code>) sowie Status-Flags (<code>sleepModeSupported</code>, <code>wakeUpOverBusSupported</code>).\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Assoziationen, Kompositionen &amp; Kardinalitäten</h5>\n<ul class=\"fig-list\"><li><strong><code>J1939TpConfig</code></strong>:\n<ul class=\"fig-list\"><li>Komponiert <code>+tpConnection 1..*</code> (<code>J1939TpConnection</code>) mit Stereotyp <code>«atpVariation,atpSplitable»</code>.\n</li><li>Komponiert <code>+tpNode 1..*</code> (<code>J1939TpNode</code>) mit Stereotyp <code>«atpVariation,atpSplitable»</code>.\n</li><li>Komponiert <code>+tpAddress 1..*</code> (<code>TpAddress</code>) mit Stereotyp <code>«atpVariation,atpSplitable»</code>.\n</li></ul>\n</li><li><strong><code>J1939TpConnection</code></strong>:\n<ul class=\"fig-list\"><li>Komponiert <code>+tpPg 0..*</code> (<code>J1939TpPg</code>).\n</li><li>Referenziert Sender/Empfänger: <code>+transmitter 0..1</code> und <code>+receiver 0..*</code> auf <code>J1939TpNode</code>.\n</li><li>Referenziert Protokoll-PDUs auf <code>NPdu</code>: <code>+flowControlPdu 1..2</code> und <code>+dataPdu 1</code>.\n</li></ul>\n</li><li><strong><code>J1939TpPg</code></strong>:\n<ul class=\"fig-list\"><li>Referenziert <code>+sdu 0..*</code> (<code>IPdu</code>) und <code>+directPdu 0..1</code> (<code>NPdu</code>).\n</li></ul>\n</li><li><strong><code>J1939TpNode</code></strong>:\n<ul class=\"fig-list\"><li>Referenziert Adressen und Hardwareanbindung: <code>+tpAddress 0..1</code> (<code>TpAddress</code>) und <code>+connector 0..1</code> (<code>CommunicationConnector</code>).\n</li></ul>\n</li><li><strong><code>PhysicalChannel</code></strong>:\n<ul class=\"fig-list\"><li>Komponiert <code>+commConnector 0..*</code> (<code>CommunicationConnector</code>) mit Stereotyp <code>«atpVariation,atpSplitable»</code>.\n</li><li>Reflexive Assoziation <code>+managedPhysicalChannel 0..*</code> auf <code>PhysicalChannel</code>.\n</li></ul>\n</li><li><strong><code>EcuInstance</code></strong>:\n<ul class=\"fig-list\"><li>Komponiert <code>+connector *</code> (<code>CommunicationConnector</code>) mit Stereotyp <code>«atpVariation,atpSplitable»</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Metamodell definiert die statische Parametrierung für zwei primäre Übertragungspfade:</p>\n<ol class=\"fig-list\"><li><strong>Broadcast Announce Message (BAM) Pfad (<code>broadcast == true</code>):</strong>\n<ul class=\"fig-list\"><li><strong>Trigger:</strong> SDU-Sendeanforderung über PduR an <code>J1939TpPg</code> mit Datenlänge &gt; 8 Byte.\n</li><li><strong>Ablauf:</strong> \n<ol class=\"fig-list\"><li>Sender (<code>transmitter</code>) emittiert TP.CM_BAM über <code>flowControlPdu</code> an die globale Broadcast-Adresse (0xFF).\n</li><li>Sequentielles Senden der Payload-Segmente über <code>dataPdu</code> (TP.DT, 1 Byte Sequence Number + 7 Bytes Payload).\n</li><li>Kein Flow-Control oder Handshake; Einhaltung des Mindestzeitabstands (50 ms bis 200 ms).\n</li><li>Alle zugeordneten <code>receiver [0..*]</code> reassemblieren paketweise.\n</li></ol>\n</li></ul>\n</li><li><strong>Point-to-Point Connection Mode (RTS/CTS) Pfad (<code>broadcast == false</code>):</strong>\n<ul class=\"fig-list\"><li><strong>Trigger:</strong> Sendeanforderung für dedizierte Zieladresse (<code>receiver [1]</code>).\n</li><li><strong>Ablauf:</strong>\n<ol class=\"fig-list\"><li><code>transmitter</code> sendet TP.CM_RTS via <code>flowControlPdu</code>.\n</li><li><code>receiver</code> prüft Puffer (<code>bufferRatio</code>) und antwortet mit TP.CM_CTS via <code>flowControlPdu</code> (vorgegebene Blockgröße via <code>maxBs</code>/<code>dynamicBs</code>).\n</li><li><code>transmitter</code> überträgt bis zu N Datenpakete via <code>dataPdu</code>.\n</li><li>Nach Blockabschluss: Receiver sendet nächstes CTS oder TP.CM_EndOfMsgACK.\n</li><li>Bei Fehler oder Pufferüberlauf: Abbruch über TP.CM_ConnAbort (sofern <code>cancellation == true</code>).\n</li></ol>\n</li></ul>\n</li><li><strong>Direktübertragungspfad (<code>directPdu [0..1]</code> konfiguriert):</strong>\n<ul class=\"fig-list\"><li>Ist die Nutzdatenlänge ≤ 8 Byte, wird das J1939-TP umgangen; der Frame wird ohne Segmentierungs-Header direkt über die referenzierte <code>NPdu</code> an das <code>CanIf</code> übergeben.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>ECUC-Ableitung (TPS_SYST_01147):</strong> Der System Extractor transformiert diese Topologie direkt in die Konfigurationsparameter des BSW-Moduls <code>J1939Tp</code> (gemäß <code>AUTOSAR_SWS_J1939TransportProtocol</code>):\n<ul class=\"fig-list\"><li><code>J1939TpConnection</code> mappt auf <code>J1939TpChannel</code> (Tx/Rx Channel Pairs).\n</li><li><code>dataPdu</code> und <code>flowControlPdu</code> korrespondieren mit <code>J1939TpPduPool</code> bzw. <code>CanIfTxPduCfg</code> / <code>CanIfRxPduCfg</code>.\n</li><li><code>sdu</code> mappt auf <code>J1939TpTxNSdu</code> / <code>J1939TpRxNSdu</code> und bindet an Routingpfade des <code>PduR</code>.\n</li></ul>\n</li><li><strong>Post-Build-Bindung (<code>vh.latestBindingTime = postBuild</code>):</strong>\n<ul class=\"fig-list\"><li>Die Kompositionen für <code>tpConnection</code>, <code>tpNode</code> und <code>tpAddress</code> tragen das Tag <code>postBuild</code>.\n</li><li>Im BSW-Code müssen Routing-Tabellen, Adresszuweisungen und PDU-IDs tabellenbasiert über Initialisierungsstrukturen (<code>J1939Tp_ConfigType</code>) realisiert werden, um Varianten im Post-Build-Flash ohne Neukompilierung austauschen zu können.\n</li></ul>\n</li><li><strong>Treiber- und Pufferallokation:</strong>\n<ul class=\"fig-list\"><li>Entwickler müssen bei gesetztem <code>dynamicBs = true</code> und variierendem <code>bufferRatio</code> dynamische Tx/Rx-Puffer im <code>J1939Tp</code> dimensionieren, um Deadlocks bei blockierenden CTS-Zuständen im Multichannel-Betrieb zu verhindern.\n</li><li>Das Vorhandensein von <code>directPdu</code> erzwingt im <code>PduR</code> und <code>J1939Tp</code> eine Laufzeit-Längenprüfung: Pakete ≤ 8 Bytes müssen auf den direkten CAN-Treiberpfad geroutet werden, um Buslast durch TP-Control-Frames zu minimieren.\n</li></ul>\n</li></ul>"}, {"id": "FIG-375235f3a51a0f49", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> AUTOSAR M2-Metamodell-Klassendiagramm (UML 2.0 Profil) aus der Spezifikation <code>AUTOSAR_TPS_SystemTemplate</code> (Kapitel Transport Layer).\n</li><li><strong>Funktionale Einordnung:</strong> Definiert die abstrakte Systembeschreibung zur Konfiguration des J1939 Transport Protocol Stacks (<code>J1939Tp</code>) innerhalb des AUTOSAR Classic Com-Stacks. Das Metamodell beschreibt die Segmentierung, Reassemblierung und das Flow-Control-Management für Parameter Groups (PGs) mit Nutzdatenlängen &gt; 8 Byte gemäß SAE J1939-21 (BAM und Point-to-Point RTS/CTS) sowie den Übergang zu CAN-Frames (<code>NPdu</code>) und Oberschicht-Paketen (<code>IPdu</code>/PduR).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Vererbungshierarchien &amp; Basisklassen</h5>\n<ul class=\"fig-list\"><li><strong><code>J1939TpConfig</code></strong> (spezialisiert die im Diagrammkopf referenzierte Superklasse <code>TpConfig</code>): Wurzelaggregat für alle J1939-TP-Artefakte eines Netzwerks.\n</li><li><strong><code>TpConnection</code></strong> (abstrakt): Basisklasse für Transportverbindungen.\n</li><li><strong><code>J1939TpConnection</code></strong> (spezialisiert <code>TpConnection</code>): Konkrete J1939-Transportverbindung.\n</li><li><strong><code>Pdu</code></strong> (abstrakt): Basisklasse für <code>IPdu</code> (Interaktionsschicht / COM) und <code>NPdu</code> (Netzwerkschicht / CAN Interface).\n</li><li><strong><code>J1939TpNode</code></strong>, <strong><code>TpAddress</code></strong>, <strong><code>PhysicalChannel</code></strong>, <strong><code>CommunicationConnector</code></strong>: Spezialisieren <code>Identifiable</code> (besitzen <code>shortName</code>, UUID etc.).\n</li><li><strong><code>EcuInstance</code></strong>: Spezialisiert <code>FibexElement</code>.\n</li></ul>\n<h5 class=\"fig-section-h5\">Entitäten &amp; Attribute</h5>\n<ul class=\"fig-list\"><li><strong><code>J1939TpConnection</code></strong>:\n<ul class=\"fig-list\"><li><code>broadcast: Boolean [0..1]</code>: Optionale Konfiguration für Broadcast Announce Message (BAM) versus Peer-to-Peer RTS/CTS.\n</li><li><code>bufferRatio: PositiveInteger [0..1]</code>: Pufferallokationsfaktor für Empfangsressourcen.\n</li><li><code>cancellation: Boolean [0..1]</code>: Unterstützung für Verbindungsabbruch (Connection Abort).\n</li><li><code>dynamicBs: Boolean [0..1]</code>: Dynamische Aushandlung der Blockgröße (Block Size).\n</li><li><code>maxBs: PositiveInteger [0..1]</code>: Maximale Blockgröße (Anzahl Frames vor nächstem CTS).\n</li><li><code>maxExpBs: PositiveInteger [0..1]</code>: Maximaler Blockgrößen-Exponent.\n</li><li><code>retry: Boolean [0..1]</code>: Aktivierung von Retransmissions bei Übertragungsfehlern.\n</li></ul>\n</li><li><strong><code>TpAddress</code></strong>:\n<ul class=\"fig-list\"><li><code>tpAddress: Integer [0..1]</code>: 8-Bit J1939-Knotenadresse (0..253 bzw. 255 für Global/Broadcast).\n</li></ul>\n</li><li><strong><code>J1939TpPg</code></strong>:\n<ul class=\"fig-list\"><li><code>pgn: Integer [0..1]</code>: Parameter Group Number (18-Bit Identifier nach SAE J1939).\n</li><li><code>requestable: Boolean [0..1]</code>: Kennzeichnet, ob die PG mittels PGN 59904 (Request PGN) angefragt werden darf.\n</li></ul>\n</li><li><strong><code>CommunicationConnector</code></strong>:\n<ul class=\"fig-list\"><li><code>createEcuWakeupSource: Boolean [0..1]</code>: Steuerung der automatischen Wakeup-Source-Generierung für das Interface.\n</li><li><code>dynamicPncToChannelMappingEnabled: Boolean [0..1]</code>: Aktiviert die dynamische Zuordnung von PNCs zu Kommunikationskanälen.\n</li><li><code>pncFilterArrayMask: PositiveInteger [0..*] {ordered}</code>: Geordnete Bitmaske für PNC-Filterung.\n</li><li><code>pncGatewayType: PncGatewayTypeEnum [0..1]</code>: Gateway-Verhalten für Partial Network Clusters.\n</li></ul>\n</li><li><strong><code>EcuInstance</code></strong>:\n<ul class=\"fig-list\"><li>Timing-Parameter (<code>comConfigurationTxTimeBase</code>, <code>comConfigurationRxTimeBase</code>, <code>comConfigurationGwTimeBase</code>, <code>pncPrepareSleepTimer</code>, <code>pnResetTime</code>), Synchronisation und PNC (<code>channelSynchronousWakeup: Boolean [0..1]</code>, <code>comEnableMDTForCyclicTransmission</code>, <code>ethSwitchPortGroupDerivation</code>, <code>pncNmRequest: Boolean [0..1]</code>, <code>pncSynchronousWakeup</code>) sowie Status-Flags (<code>sleepModeSupported: Boolean [0..1]</code>, <code>v2xSupported: V2xSupportEnum [0..1]</code>, <code>wakeUpOverBusSupported: Boolean [0..1]</code>).\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Assoziationen, Kompositionen &amp; Kardinalitäten</h5>\n<ul class=\"fig-list\"><li><strong><code>J1939TpConfig</code></strong>:\n<ul class=\"fig-list\"><li>Komponiert <code>+tpConnection 0..*</code> (<code>J1939TpConnection</code>) mit Stereotyp <code>«atpVariation,atpSplitable»</code>.\n</li><li>Komponiert <code>+tpNode 0..*</code> (<code>J1939TpNode</code>) mit Stereotyp <code>«atpVariation,atpSplitable»</code>.\n</li><li>Komponiert <code>+tpAddress 0..*</code> (<code>TpAddress</code>) mit Stereotyp <code>«atpVariation,atpSplitable»</code>.\n</li></ul>\n</li><li><strong><code>J1939TpConnection</code></strong>:\n<ul class=\"fig-list\"><li>Komponiert <code>+tpPg 0..*</code> (<code>J1939TpPg</code>).\n</li><li>Referenziert Sender/Empfänger: <code>+transmitter 0..1</code> und <code>+receiver 0..*</code> auf <code>J1939TpNode</code>.\n</li><li>Referenziert Protokoll-PDUs auf <code>NPdu</code>: <code>+flowControlPdu 0..2</code> und <code>+dataPdu 0..1</code>.\n</li></ul>\n</li><li><strong><code>J1939TpPg</code></strong>:\n<ul class=\"fig-list\"><li>Referenziert <code>+sdu 0..*</code> (<code>IPdu</code>) und <code>+directPdu 0..1</code> (<code>NPdu</code>).\n</li></ul>\n</li><li><strong><code>J1939TpNode</code></strong>:\n<ul class=\"fig-list\"><li>Referenziert Adressen und Hardwareanbindung: <code>+tpAddress 0..1</code> (<code>TpAddress</code>) und <code>+connector 0..1</code> (<code>CommunicationConnector</code>).\n</li></ul>\n</li><li><strong><code>PhysicalChannel</code></strong>:\n<ul class=\"fig-list\"><li>Komponiert <code>+commConnector 0..*</code> (<code>CommunicationConnector</code>) mit Stereotyp <code>«atpVariation,atpSplitable»</code>.\n</li><li>Reflexive Assoziation <code>+managedPhysicalChannel 0..*</code> auf <code>PhysicalChannel</code>.\n</li></ul>\n</li><li><strong><code>EcuInstance</code></strong>:\n<ul class=\"fig-list\"><li>Komponiert <code>+connector *</code> (<code>CommunicationConnector</code>) mit Stereotyp <code>«atpVariation,atpSplitable»</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Metamodell definiert die statische Parametrierung für zwei primäre Übertragungspfade:</p>\n<ol class=\"fig-list\"><li><strong>Broadcast Announce Message (BAM) Pfad (<code>broadcast == true</code>):</strong>\n<ul class=\"fig-list\"><li><strong>Trigger:</strong> SDU-Sendeanforderung über PduR an <code>J1939TpPg</code> mit Datenlänge &gt; 8 Byte.\n</li><li><strong>Ablauf:</strong> \n<ol class=\"fig-list\"><li>Sender (<code>transmitter</code>) emittiert TP.CM_BAM über <code>flowControlPdu</code> an die globale Broadcast-Adresse (0xFF).\n</li><li>Sequentielles Senden der Payload-Segmente über <code>dataPdu</code> (TP.DT, 1 Byte Sequence Number + 7 Bytes Payload).\n</li><li>Kein Flow-Control oder Handshake; Einhaltung des Mindestzeitabstands (50 ms bis 200 ms).\n</li><li>Alle zugeordneten <code>receiver [0..*]</code> reassemblieren paketweise.\n</li></ol>\n</li></ul>\n</li><li><strong>Point-to-Point Connection Mode (RTS/CTS) Pfad (<code>broadcast == false</code>):</strong>\n<ul class=\"fig-list\"><li><strong>Trigger:</strong> Sendeanforderung für dedizierte Zieladresse (<code>receiver [1]</code>).\n</li><li><strong>Ablauf:</strong>\n<ol class=\"fig-list\"><li><code>transmitter</code> sendet TP.CM_RTS via <code>flowControlPdu</code>.\n</li><li><code>receiver</code> prüft Puffer (<code>bufferRatio</code>) und antwortet mit TP.CM_CTS via <code>flowControlPdu</code> (vorgegebene Blockgröße via <code>maxBs</code>/<code>dynamicBs</code>).\n</li><li><code>transmitter</code> überträgt bis zu N Datenpakete via <code>dataPdu</code>.\n</li><li>Nach Blockabschluss: Receiver sendet nächstes CTS oder TP.CM_EndOfMsgACK.\n</li><li>Bei Fehler oder Pufferüberlauf: Abbruch über TP.CM_ConnAbort (sofern <code>cancellation == true</code>).\n</li></ol>\n</li></ul>\n</li><li><strong>Direktübertragungspfad (<code>directPdu [0..1]</code> konfiguriert):</strong>\n<ul class=\"fig-list\"><li>Ist die Nutzdatenlänge ≤ 8 Byte, wird das J1939-TP umgangen; der Frame wird ohne Segmentierungs-Header direkt über die referenzierte <code>NPdu</code> an das <code>CanIf</code> übergeben.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>ECUC-Ableitung (TPS_SYST_01147):</strong> Der System Extractor transformiert diese Topologie direkt in die Konfigurationsparameter des BSW-Moduls <code>J1939Tp</code> (gemäß <code>AUTOSAR_SWS_J1939TransportProtocol</code>):\n<ul class=\"fig-list\"><li><code>J1939TpConnection</code> mappt auf <code>J1939TpChannel</code> (Tx/Rx Channel Pairs).\n</li><li><code>dataPdu</code> und <code>flowControlPdu</code> korrespondieren mit <code>J1939TpPduPool</code> bzw. <code>CanIfTxPduCfg</code> / <code>CanIfRxPduCfg</code>.\n</li><li><code>sdu</code> mappt auf <code>J1939TpTxNSdu</code> / <code>J1939TpRxNSdu</code> und bindet an Routingpfade des <code>PduR</code>.\n</li></ul>\n</li><li><strong>Post-Build-Bindung (<code>vh.latestBindingTime = postBuild</code>):</strong>\n<ul class=\"fig-list\"><li>Die Kompositionen für <code>tpConnection</code>, <code>tpNode</code> und <code>tpAddress</code> tragen das Tag <code>postBuild</code>.\n</li><li>Im BSW-Code müssen Routing-Tabellen, Adresszuweisungen und PDU-IDs tabellenbasiert über Initialisierungsstrukturen (<code>J1939Tp_ConfigType</code>) realisiert werden, um Varianten im Post-Build-Flash ohne Neukompilierung austauschen zu können.\n</li></ul>\n</li><li><strong>Treiber- und Pufferallokation:</strong>\n<ul class=\"fig-list\"><li>Entwickler müssen bei gesetztem <code>dynamicBs = true</code> und variierendem <code>bufferRatio</code> dynamische Tx/Rx-Puffer im <code>J1939Tp</code> dimensionieren, um Deadlocks bei blockierenden CTS-Zuständen im Multichannel-Betrieb zu verhindern.\n</li><li>Das Vorhandensein von <code>directPdu</code> erzwingt im <code>PduR</code> und <code>J1939Tp</code> eine Laufzeit-Längenprüfung: Pakete ≤ 8 Bytes müssen auf den direkten CAN-Treiberpfad geroutet werden, um Buslast durch TP-Control-Frames zu minimieren.\n</li></ul>\n</li></ul>"}, {"id": "FIG-adb7e688af117003", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> AUTOSAR M2-Metamodell-Klassendiagramm (UML 2.0 Profil) aus der Spezifikation <code>AUTOSAR_TPS_SystemTemplate</code> (Kapitel Transport Layer).\n</li><li><strong>Funktionale Einordnung:</strong> Definiert die abstrakte Systembeschreibung zur Konfiguration des J1939 Transport Protocol Stacks (<code>J1939Tp</code>) innerhalb des AUTOSAR Classic Com-Stacks. Das Metamodell beschreibt die Segmentierung, Reassemblierung und das Flow-Control-Management für Parameter Groups (PGs) mit Nutzdatenlängen &gt; 8 Byte gemäß SAE J1939-21 (BAM und Point-to-Point RTS/CTS) sowie den Übergang zu CAN-Frames (<code>NPdu</code>) und Oberschicht-Paketen (<code>IPdu</code>/PduR).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Vererbungshierarchien &amp; Basisklassen</h5>\n<ul class=\"fig-list\"><li><strong><code>J1939TpConfig</code></strong> (spezialisiert die im Diagrammkopf referenzierte Superklasse <code>TpConfig</code>): Wurzelaggregat für alle J1939-TP-Artefakte eines Netzwerks.\n</li><li><strong><code>TpConnection</code></strong> (abstrakt): Basisklasse für Transportverbindungen.\n</li><li><strong><code>J1939TpConnection</code></strong> (spezialisiert <code>TpConnection</code>): Konkrete J1939-Transportverbindung.\n</li><li><strong><code>Pdu</code></strong> (abstrakt): Basisklasse für <code>IPdu</code> (Interaktionsschicht / COM) und <code>NPdu</code> (Netzwerkschicht / CAN Interface).\n</li><li><strong><code>J1939TpNode</code></strong>, <strong><code>TpAddress</code></strong>, <strong><code>PhysicalChannel</code></strong>, <strong><code>CommunicationConnector</code></strong>: Spezialisieren <code>Identifiable</code> (besitzen <code>shortName</code>, UUID etc.).\n</li><li><strong><code>EcuInstance</code></strong>: Spezialisiert <code>FibexElement</code>.\n</li></ul>\n<h5 class=\"fig-section-h5\">Entitäten &amp; Attribute</h5>\n<ul class=\"fig-list\"><li><strong><code>J1939TpConnection</code></strong>:\n<ul class=\"fig-list\"><li><code>acceptVariableDA: Boolean [0..1]</code>: Akzeptanz variabler Zieladressen (Destination Addresses).\n</li><li><code>acceptVariableSA: Boolean [0..1]</code>: Akzeptanz variabler Quelladressen (Source Addresses).\n</li><li><code>broadcast: Boolean [0..1]</code>: Optionale Konfiguration für Broadcast Announce Message (BAM) versus Peer-to-Peer RTS/CTS.\n</li><li><code>bufferRatio: PositiveInteger [0..1]</code>: Pufferallokationsfaktor für Empfangsressourcen.\n</li><li><code>cancellation: Boolean [0..1]</code>: Unterstützung für Verbindungsabbruch (Connection Abort).\n</li><li><code>dynamicBs: Boolean [0..1]</code>: Dynamische Aushandlung der Blockgröße (Block Size).\n</li><li><code>maxBs: PositiveInteger [0..1]</code>: Maximale Blockgröße (Anzahl Frames vor nächstem CTS).\n</li><li><code>maxExpBs: PositiveInteger [0..1]</code>: Maximaler Blockgrößen-Exponent.\n</li><li><code>retry: Boolean [0..1]</code>: Aktivierung von Retransmissions bei Übertragungsfehlern.\n</li><li><code>tpProtocolType: J1939TpProtocolTypeEnum [0..1]</code>: Spezifikation des Transportprotokoll-Typs.\n</li><li><code>useVariableDA: Boolean [0..1]</code>: Verwendung dynamischer/variabler Zieladressen.\n</li><li><code>useVariableSA: Boolean [0..1]</code>: Verwendung dynamischer/variabler Quelladressen.\n</li></ul>\n</li><li><strong><code>TpAddress</code></strong>:\n<ul class=\"fig-list\"><li><code>tpAddress: Integer [0..1]</code>: 8-Bit J1939-Knotenadresse (0..253 bzw. 255 für Global/Broadcast).\n</li></ul>\n</li><li><strong><code>J1939TpPg</code></strong>:\n<ul class=\"fig-list\"><li><code>pgn: Integer [0..1]</code>: Parameter Group Number (18-Bit Identifier nach SAE J1939).\n</li><li><code>requestable: Boolean [0..1]</code>: Kennzeichnet, ob die PG mittels PGN 59904 (Request PGN) angefragt werden darf.\n</li></ul>\n</li><li><strong><code>CommunicationConnector</code></strong>:\n<ul class=\"fig-list\"><li><code>createEcuWakeupSource: Boolean [0..1]</code>: Steuerung der automatischen Wakeup-Source-Generierung für das Interface.\n</li><li><code>dynamicPncToChannelMappingEnabled: Boolean [0..1]</code>: Aktiviert die dynamische Zuordnung von PNCs zu Kommunikationskanälen.\n</li><li><code>pncFilterArrayMask: PositiveInteger [0..*] {ordered}</code>: Geordnete Bitmaske für PNC-Filterung.\n</li><li><code>pncGatewayType: PncGatewayTypeEnum [0..1]</code>: Gateway-Verhalten für Partial Network Clusters.\n</li></ul>\n</li><li><strong><code>EcuInstance</code></strong>:\n<ul class=\"fig-list\"><li>Timing-Parameter (<code>comConfigurationTxTimeBase</code>, <code>comConfigurationRxTimeBase</code>, <code>comConfigurationGwTimeBase</code>, <code>pncPrepareSleepTimer</code>, <code>pnResetTime</code>), Synchronisation und PNC (<code>channelSynchronousWakeup: Boolean [0..1]</code>, <code>comEnableMDTForCyclicTransmission</code>, <code>ethSwitchPortGroupDerivation</code>, <code>pncNmRequest: Boolean [0..1]</code>, <code>pncSynchronousWakeup</code>) sowie Status-Flags (<code>sleepModeSupported: Boolean [0..1]</code>, <code>v2xSupported: V2xSupportEnum [0..1]</code>, <code>wakeUpOverBusSupported: Boolean [0..1]</code>).\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Assoziationen, Kompositionen &amp; Kardinalitäten</h5>\n<ul class=\"fig-list\"><li><strong><code>J1939TpConfig</code></strong>:\n<ul class=\"fig-list\"><li>Komponiert <code>+tpConnection 0..*</code> (<code>J1939TpConnection</code>) mit Stereotyp <code>«atpVariation,atpSplitable»</code>.\n</li><li>Komponiert <code>+tpNode 0..*</code> (<code>J1939TpNode</code>) mit Stereotyp <code>«atpVariation,atpSplitable»</code>.\n</li><li>Komponiert <code>+tpAddress 0..*</code> (<code>TpAddress</code>) mit Stereotyp <code>«atpVariation,atpSplitable»</code>.\n</li></ul>\n</li><li><strong><code>J1939TpConnection</code></strong>:\n<ul class=\"fig-list\"><li>Komponiert <code>+tpPg 0..*</code> (<code>J1939TpPg</code>).\n</li><li>Referenziert Sender/Empfänger: <code>+transmitter 0..1</code> und <code>+receiver 0..*</code> auf <code>J1939TpNode</code>.\n</li><li>Referenziert Protokoll-PDUs auf <code>NPdu</code>: <code>+flowControlPdu 0..2</code> und <code>+dataPdu 0..1</code>.\n</li></ul>\n</li><li><strong><code>J1939TpPg</code></strong>:\n<ul class=\"fig-list\"><li>Referenziert <code>+sdu 0..*</code> (<code>IPdu</code>) und <code>+directPdu 0..1</code> (<code>NPdu</code>).\n</li></ul>\n</li><li><strong><code>J1939TpNode</code></strong>:\n<ul class=\"fig-list\"><li>Referenziert Adressen und Hardwareanbindung: <code>+tpAddress 0..1</code> (<code>TpAddress</code>) und <code>+connector 0..1</code> (<code>CommunicationConnector</code>).\n</li></ul>\n</li><li><strong><code>PhysicalChannel</code></strong>:\n<ul class=\"fig-list\"><li>Komponiert <code>+commConnector 0..*</code> (<code>CommunicationConnector</code>) mit Stereotyp <code>«atpVariation,atpSplitable»</code>.\n</li><li>Reflexive Assoziation <code>+managedPhysicalChannel 0..*</code> auf <code>PhysicalChannel</code>.\n</li></ul>\n</li><li><strong><code>EcuInstance</code></strong>:\n<ul class=\"fig-list\"><li>Komponiert <code>+connector *</code> (<code>CommunicationConnector</code>) mit Stereotyp <code>«atpVariation,atpSplitable»</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Metamodell definiert die statische Parametrierung für zwei primäre Übertragungspfade:</p>\n<ol class=\"fig-list\"><li><strong>Broadcast Announce Message (BAM) Pfad (<code>broadcast == true</code>):</strong>\n<ul class=\"fig-list\"><li><strong>Trigger:</strong> SDU-Sendeanforderung über PduR an <code>J1939TpPg</code> mit Datenlänge &gt; 8 Byte.\n</li><li><strong>Ablauf:</strong> \n<ol class=\"fig-list\"><li>Sender (<code>transmitter</code>) emittiert TP.CM_BAM über <code>flowControlPdu</code> an die globale Broadcast-Adresse (0xFF).\n</li><li>Sequentielles Senden der Payload-Segmente über <code>dataPdu</code> (TP.DT, 1 Byte Sequence Number + 7 Bytes Payload).\n</li><li>Kein Flow-Control oder Handshake; Einhaltung des Mindestzeitabstands (50 ms bis 200 ms).\n</li><li>Alle zugeordneten <code>receiver [0..*]</code> reassemblieren paketweise.\n</li></ol>\n</li></ul>\n</li><li><strong>Point-to-Point Connection Mode (RTS/CTS) Pfad (<code>broadcast == false</code>):</strong>\n<ul class=\"fig-list\"><li><strong>Trigger:</strong> Sendeanforderung für dedizierte Zieladresse (<code>receiver [1]</code>).\n</li><li><strong>Ablauf:</strong>\n<ol class=\"fig-list\"><li><code>transmitter</code> sendet TP.CM_RTS via <code>flowControlPdu</code>.\n</li><li><code>receiver</code> prüft Puffer (<code>bufferRatio</code>) und antwortet mit TP.CM_CTS via <code>flowControlPdu</code> (vorgegebene Blockgröße via <code>maxBs</code>/<code>dynamicBs</code>).\n</li><li><code>transmitter</code> überträgt bis zu N Datenpakete via <code>dataPdu</code>.\n</li><li>Nach Blockabschluss: Receiver sendet nächstes CTS oder TP.CM_EndOfMsgACK.\n</li><li>Bei Fehler oder Pufferüberlauf: Abbruch über TP.CM_ConnAbort (sofern <code>cancellation == true</code>).\n</li></ol>\n</li></ul>\n</li><li><strong>Direktübertragungspfad (<code>directPdu [0..1]</code> konfiguriert):</strong>\n<ul class=\"fig-list\"><li>Ist die Nutzdatenlänge ≤ 8 Byte, wird das J1939-TP umgangen; der Frame wird ohne Segmentierungs-Header direkt über die referenzierte <code>NPdu</code> an das <code>CanIf</code> übergeben.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>ECUC-Ableitung (TPS_SYST_01147):</strong> Der System Extractor transformiert diese Topologie direkt in die Konfigurationsparameter des BSW-Moduls <code>J1939Tp</code> (gemäß <code>AUTOSAR_SWS_J1939TransportProtocol</code>):\n<ul class=\"fig-list\"><li><code>J1939TpConnection</code> mappt auf <code>J1939TpChannel</code> (Tx/Rx Channel Pairs).\n</li><li><code>dataPdu</code> und <code>flowControlPdu</code> korrespondieren mit <code>J1939TpPduPool</code> bzw. <code>CanIfTxPduCfg</code> / <code>CanIfRxPduCfg</code>.\n</li><li><code>sdu</code> mappt auf <code>J1939TpTxNSdu</code> / <code>J1939TpRxNSdu</code> und bindet an Routingpfade des <code>PduR</code>.\n</li></ul>\n</li><li><strong>Post-Build-Bindung (<code>vh.latestBindingTime = postBuild</code>):</strong>\n<ul class=\"fig-list\"><li>Die Kompositionen für <code>tpConnection</code>, <code>tpNode</code> und <code>tpAddress</code> tragen das Tag <code>postBuild</code>.\n</li><li>Im BSW-Code müssen Routing-Tabellen, Adresszuweisungen und PDU-IDs tabellenbasiert über Initialisierungsstrukturen (<code>J1939Tp_ConfigType</code>) realisiert werden, um Varianten im Post-Build-Flash ohne Neukompilierung austauschen zu können.\n</li></ul>\n</li><li><strong>Treiber- und Pufferallokation:</strong>\n<ul class=\"fig-list\"><li>Entwickler müssen bei gesetztem <code>dynamicBs = true</code> und variierendem <code>bufferRatio</code> dynamische Tx/Rx-Puffer im <code>J1939Tp</code> dimensionieren, um Deadlocks bei blockierenden CTS-Zuständen im Multichannel-Betrieb zu verhindern.\n</li><li>Das Vorhandensein von <code>directPdu</code> erzwingt im <code>PduR</code> und <code>J1939Tp</code> eine Laufzeit-Längenprüfung: Pakete ≤ 8 Bytes müssen auf den direkten CAN-Treiberpfad geroutet werden, um Buslast durch TP-Control-Frames zu minimieren.\n</li></ul>\n</li></ul>"}, {"id": "FIG-a02dcd2cef80aea1", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> AUTOSAR M2-Metamodell-Klassendiagramm (UML 2.0 Profil) aus der Spezifikation <code>AUTOSAR_TPS_SystemTemplate</code> (Kapitel Transport Layer).\n</li><li><strong>Funktionale Einordnung:</strong> Definiert die abstrakte Systembeschreibung zur Konfiguration des J1939 Transport Protocol Stacks (<code>J1939Tp</code>) innerhalb des AUTOSAR Classic Com-Stacks. Das Metamodell beschreibt die Segmentierung, Reassemblierung und das Flow-Control-Management für Parameter Groups (PGs) mit Nutzdatenlängen &gt; 8 Byte gemäß SAE J1939-21 (BAM und Point-to-Point RTS/CTS) sowie den Übergang zu CAN-Frames (<code>NPdu</code>) und Oberschicht-Paketen (<code>IPdu</code>/PduR).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Vererbungshierarchien &amp; Basisklassen</h5>\n<ul class=\"fig-list\"><li><strong><code>J1939TpConfig</code></strong> (spezialisiert die im Diagrammkopf referenzierte Superklasse <code>TpConfig</code>): Wurzelaggregat für alle J1939-TP-Artefakte eines Netzwerks.\n</li><li><strong><code>TpConnection</code></strong> (abstrakt): Basisklasse für Transportverbindungen.\n</li><li><strong><code>J1939TpConnection</code></strong> (spezialisiert <code>TpConnection</code>): Konkrete J1939-Transportverbindung.\n</li><li><strong><code>Pdu</code></strong> (abstrakt): Basisklasse für <code>IPdu</code> (Interaktionsschicht / COM) und <code>NPdu</code> (Netzwerkschicht / CAN Interface).\n</li><li><strong><code>J1939TpNode</code></strong>, <strong><code>TpAddress</code></strong>, <strong><code>PhysicalChannel</code></strong>, <strong><code>CommunicationConnector</code></strong>: Spezialisieren <code>Identifiable</code> (besitzen <code>shortName</code>, UUID etc.).\n</li><li><strong><code>EcuInstance</code></strong>: Spezialisiert <code>FibexElement</code>.\n</li></ul>\n<h5 class=\"fig-section-h5\">Entitäten &amp; Attribute</h5>\n<ul class=\"fig-list\"><li><strong><code>J1939TpConnection</code></strong>:\n<ul class=\"fig-list\"><li><code>acceptVariableDA: Boolean [0..1]</code>: Akzeptanz variabler Zieladressen (Destination Addresses).\n</li><li><code>acceptVariableSA: Boolean [0..1]</code>: Akzeptanz variabler Quelladressen (Source Addresses).\n</li><li><code>bamTiming: TimeValue [0..1]</code>: Zeitabstand bzw. Timing für Broadcast Announce Message (BAM) Frame-Übertragungen.\n</li><li><code>bufferRatio: PositiveInteger [0..1]</code>: Pufferallokationsfaktor für Empfangsressourcen.\n</li><li><code>cancellation: Boolean [0..1]</code>: Unterstützung für Verbindungsabbruch (Connection Abort).\n</li><li><code>dynamicBs: Boolean [0..1]</code>: Dynamische Aushandlung der Blockgröße (Block Size).\n</li><li><code>maxBs: PositiveInteger [0..1]</code>: Maximale Blockgröße (Anzahl Frames vor nächstem CTS).\n</li><li><code>maxExpBs: PositiveInteger [0..1]</code>: Maximaler Blockgrößen-Exponent.\n</li><li><code>retry: Boolean [0..1]</code>: Aktivierung von Retransmissions bei Übertragungsfehlern.\n</li><li><code>tpProtocolType: J1939TpProtocolTypeEnum [0..1]</code>: Spezifikation des Transportprotokoll-Typs.\n</li><li><code>txPduPriority: PositiveInteger [0..1]</code>: Priorität für gesendete Transport-Layer-PDUs.\n</li><li><code>useVariableDA: Boolean [0..1]</code>: Verwendung dynamischer/variabler Zieladressen.\n</li><li><code>useVariableSA: Boolean [0..1]</code>: Verwendung dynamischer/variabler Quelladressen.\n</li></ul>\n</li><li><strong><code>TpAddress</code></strong>:\n<ul class=\"fig-list\"><li><code>tpAddress: Integer [0..1]</code>: 8-Bit J1939-Knotenadresse (0..253 bzw. 255 für Global/Broadcast).\n</li></ul>\n</li><li><strong><code>J1939TpPg</code></strong>:\n<ul class=\"fig-list\"><li><code>pgn: Integer [0..1]</code>: Parameter Group Number (18-Bit Identifier nach SAE J1939).\n</li><li><code>requestable: Boolean [0..1]</code>: Kennzeichnet, ob die PG mittels PGN 59904 (Request PGN) angefragt werden darf.\n</li><li><code>txDirectPduPriority: PositiveInteger [0..1]</code>: Priorität für gesendete Direkt-PDUs.\n</li></ul>\n</li><li><strong><code>CommunicationConnector</code></strong>:\n<ul class=\"fig-list\"><li><code>createEcuWakeupSource: Boolean [0..1]</code>: Steuerung der automatischen Wakeup-Source-Generierung für das Interface.\n</li><li><code>dynamicPncToChannelMappingEnabled: Boolean [0..1]</code>: Aktiviert die dynamische Zuordnung von PNCs zu Kommunikationskanälen.\n</li><li><code>pncFilterArrayMask: PositiveInteger [0..*] {ordered}</code>: Geordnete Bitmaske für PNC-Filterung.\n</li><li><code>pncGatewayType: PncGatewayTypeEnum [0..1]</code>: Gateway-Verhalten für Partial Network Clusters.\n</li></ul>\n</li><li><strong><code>EcuInstance</code></strong>:\n<ul class=\"fig-list\"><li>Timing-Parameter (<code>comConfigurationTxTimeBase</code>, <code>comConfigurationRxTimeBase</code>, <code>comConfigurationGwTimeBase</code>, <code>pnResetTime</code>, <code>pncPrepareSleepTimer</code>).\n</li><li>Steuerflags für Wake-up und Power-Management (<code>channelSynchronousWakeup</code>, <code>comEnableMDTForCyclicTransmission</code>, <code>ethSwitchPortGroupDerivation</code>, <code>pncNmRequest</code>, <code>pncSynchronousWakeup</code>, <code>sleepModeSupported</code>, <code>v2xSupported</code>, <code>wakeUpOverBusSupported</code>).\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Assoziationen &amp; Kardinalitäten</h5>\n<ul class=\"fig-list\"><li><strong><code>J1939TpConfig</code></strong>:\n<ul class=\"fig-list\"><li>Komposition <code>+tpConnection 0..*</code> zu <code>J1939TpConnection</code> (Stereotyp «atpVariation,atpSplitable»).\n</li><li>Komposition <code>+tpNode 0..*</code> zu <code>J1939TpNode</code> (Stereotyp «atpVariation,atpSplitable»).\n</li><li>Komposition <code>+tpAddress 0..*</code> zu <code>TpAddress</code> (Stereotyp «atpVariation,atpSplitable»).\n</li></ul>\n</li><li><strong><code>J1939TpConnection</code></strong>:\n<ul class=\"fig-list\"><li>Assoziation <code>+transmitter 0..1</code> zu <code>J1939TpNode</code>.\n</li><li>Assoziation <code>+receiver 0..*</code> zu <code>J1939TpNode</code>.\n</li><li>Komposition <code>+flowControlPdu 0..2</code> zu <code>NPdu</code> (CAN-Frames für RTS, CTS, EndofMsgAck, ConnAbort).\n</li><li>Assoziation <code>+dataPdu 0..1</code> zu <code>NPdu</code> (CAN-Frames für TP.DT Data Transfer).\n</li><li>Komposition <code>+tpPg 0..*</code> zu <code>J1939TpPg</code> (Stereotyp «atpVariation,atpSplitable»).\n</li></ul>\n</li><li><strong><code>J1939TpNode</code></strong>:\n<ul class=\"fig-list\"><li>Assoziation <code>+tpAddress 0..1</code> zu <code>TpAddress</code>.\n</li><li>Assoziation <code>+connector 0..1</code> zu <code>CommunicationConnector</code>.\n</li></ul>\n</li><li><strong><code>J1939TpPg</code></strong>:\n<ul class=\"fig-list\"><li>Assoziation <code>+sdu 0..*</code> zu <code>IPdu</code> (referenziert die zu übertragenden Nutzdaten-PDUs).\n</li><li>Assoziation <code>+directPdu 0..1</code> zu <code>NPdu</code> (direkte CAN-Frame-Übertragung bei Nachrichten ≤ 8 Byte).\n</li></ul>\n</li><li><strong><code>CommunicationConnector</code> / <code>PhysicalChannel</code> / <code>EcuInstance</code></strong>:\n<ul class=\"fig-list\"><li><code>CommunicationConnector</code> referenziert <code>+managedPhysicalChannel 0..*</code> (<code>PhysicalChannel</code>).\n</li><li><code>EcuInstance</code> aggregiert via Komposition <code>+commConnector 0..*</code> (<code>CommunicationConnector</code>, Stereotyp «atpVariation,atpSplitable»).\n</li><li><code>CommunicationConnector</code> verweist via Assoziation <code>+connector *</code> auf <code>EcuInstance</code> (Stereotyp «atpVariation,atpSplitable»).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Verbindungsaufbau &amp; Protokollauswahl:</strong> Eine <code>J1939TpConnection</code> steuert über <code>tpProtocolType</code> und Adressierungsmerkmale (<code>acceptVariableDA</code>, <code>acceptVariableSA</code>, <code>useVariableDA</code>, <code>useVariableSA</code>) den SAE J1939 TP-Transfer.\n</li><li><strong>RTS/CTS (Peer-to-Peer):</strong> Ein Sender (<code>transmitter</code>) initiiert die Verbindung über eine <code>flowControlPdu</code> (Request to Send). Der Empfänger (<code>receiver</code>) antwortet mit Clear to Send (CTS), woraufhin Daten-Frames (<code>dataPdu</code>, TP.DT) unter Berücksichtigung von <code>maxBs</code> bzw. <code>dynamicBs</code> übermittelt werden. Der Transfer wird mit <code>EndOfMessageACK</code> über <code>flowControlPdu</code> bestätigt oder im Fehlerfall via ConnectionAbort abgebrochen (<code>cancellation</code>).\n</li><li><strong>Broadcast Announce Message (BAM):</strong> Daten-Frames (<code>dataPdu</code>) werden im durch <code>bamTiming</code> spezifizierten zeitlichen Intervall an die globale Adresse gesendet, ohne dass Flow-Control-Antworten erwartet werden.\n</li><li><strong>Prioritätssteuerung:</strong> Die Priorisierung der CAN-Nachrichten wird für segmentierte Übertragungen über <code>txPduPriority</code> an der <code>J1939TpConnection</code> und für Direktübertragungen über <code>txDirectPduPriority</code> an der <code>J1939TpPg</code> festgelegt.\n</li><li><strong>Direct PDU Bypass:</strong> Handelt es sich um Parameter Groups mit Nutzdaten ≤ 8 Byte, wird über <code>J1939TpPg.directPdu</code> ohne Transportprotokoll-Overhead direkt auf die CAN-Ebene (<code>NPdu</code>) durchgeroutet.\n</li><li><strong>Topologische Bindung:</strong> Die Zuordnung eines <code>J1939TpNode</code> über <code>CommunicationConnector</code> zum <code>PhysicalChannel</code> der <code>EcuInstance</code> gewährleistet die deterministische Zuweisung der J1939-Knotenadresse (<code>TpAddress</code>) zum jeweiligen CAN-Kanal.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>ECUC-Ableitung (TPS_SYST_01147):</strong> Der System Extractor transformiert diese Topologie direkt in die Konfigurationsparameter des BSW-Moduls <code>J1939Tp</code> (gemäß <code>AUTOSAR_SWS_J1939TransportProtocol</code>):\n<ul class=\"fig-list\"><li><code>J1939TpConnection</code> mappt auf <code>J1939TpChannel</code> (Tx/Rx Channel Pairs).\n</li><li><code>dataPdu</code> und <code>flowControlPdu</code> korrespondieren mit <code>J1939TpPduPool</code> bzw. <code>CanIfTxPduCfg</code> / <code>CanIfRxPduCfg</code>.\n</li><li><code>sdu</code> mappt auf <code>J1939TpTxNSdu</code> / <code>J1939TpRxNSdu</code> und bindet an Routingpfade des <code>PduR</code>.\n</li></ul>\n</li><li><strong>Post-Build-Bindung (<code>vh.latestBindingTime = postBuild</code>):</strong>\n<ul class=\"fig-list\"><li>Die Kompositionen für <code>tpConnection</code>, <code>tpNode</code> und <code>tpAddress</code> tragen das Tag <code>postBuild</code>.\n</li><li>Im BSW-Code müssen Routing-Tabellen, Adresszuweisungen und PDU-IDs tabellenbasiert über Initialisierungsstrukturen (<code>J1939Tp_ConfigType</code>) realisiert werden, um Varianten im Post-Build-Flash ohne Neukompilierung austauschen zu können.\n</li></ul>\n</li><li><strong>Treiber- und Pufferallokation:</strong>\n<ul class=\"fig-list\"><li>Entwickler müssen bei gesetztem <code>dynamicBs = true</code> und variierendem <code>bufferRatio</code> dynamische Tx/Rx-Puffer im <code>J1939Tp</code> dimensionieren, um Deadlocks bei blockierenden CTS-Zuständen im Multichannel-Betrieb zu verhindern.\n</li><li>Das Vorhandensein von <code>directPdu</code> erzwingt im <code>PduR</code> und <code>J1939Tp</code> eine Laufzeit-Längenprüfung: Pakete ≤ 8 Bytes müssen auf den direkten CAN-Treiberpfad geroutet werden, um Buslast durch TP-Control-Frames zu minimieren.\n</li></ul>\n</li></ul>"}], "trans": [{"from": "FIG-8132b4e23057509d", "to": "FIG-0e020b2804484a6e", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong><code>PhysicalChannel</code></strong>: Neue reflexive Assoziation <code>+managedPhysicalChannel 0..*</code> ergänzt.\n</li><li><strong><code>J1939TpConfig</code></strong>: An den Kompositionen <code>+tpConnection</code>, <code>+tpNode</code> und <code>+tpAddress</code> entfallen die expliziten Tag-Notizen (<code>Tags: vh.latestBindingTime = postBuild</code>), der Stereotyp <code>«atpVariation»</code> verbleibt.\n</li><li><strong>Layout / Typografie</strong>: Leerzeichen vor Doppelpunkten bei Attributtypen vereinheitlicht.\n</li></ul>"}, {"from": "FIG-0e020b2804484a6e", "to": "FIG-2db868dee23c47f6", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong><code>EcuInstance</code></strong>: Attribut <code>diagnosticAddress :Integer [0..1]</code> entfernt; neues Attribut <code>pncSynchronousWakeup :Boolean [0..1]</code> ergänzt.\n</li><li><strong><code>CommunicationConnector</code></strong>: Neues Attribut <code>createEcuWakeupSource :Boolean [0..1]</code> ergänzt.\n</li><li><strong><code>EcuInstance</code> -&gt; <code>CommunicationConnector</code></strong>: An der Komposition <code>+connector *</code> wurde der Stereotyp <code>«atpVariation»</code> ergänzt.\n</li><li><strong><code>TpConfig</code></strong>: Die separate übergeordnete Vererbungsbox für <code>FibexElement / TpConfig</code> mit Generalisierungspfeil wurde durch die kompakte UML-Superklassen-Notation <code>TpConfig</code> oben rechts im Kopf von <code>J1939TpConfig</code> ersetzt.\n</li></ul>"}, {"from": "FIG-2db868dee23c47f6", "to": "FIG-f35d4a7e2f441363", "fr": "R19-11", "tr": "R20-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong><code>CommunicationConnector</code></strong>: Neues Attribut <code>dynamicPncToChannelMappingEnabled :Boolean [0..1]</code> ergänzt.\n</li></ul>"}, {"from": "FIG-f35d4a7e2f441363", "to": "FIG-be9824606273cce4", "fr": "R20-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong><code>CommunicationConnector</code></strong>: Neues Attribut <code>pncFilterArrayMask :PositiveInteger [0..*] {ordered}</code> ergänzt.\n</li><li><strong><code>EcuInstance</code></strong>: Neues Attribut <code>pncNmRequest :Boolean [0..1]</code> ergänzt.\n</li><li><strong>Stereotypen</strong>: Der Stereotyp an den Kompositionen von <code>J1939TpConfig</code> (<code>+tpConnection</code>, <code>+tpNode</code>, <code>+tpAddress</code>), an <code>PhysicalChannel</code> (<code>+commConnector</code>) sowie an <code>EcuInstance</code> (<code>+connector</code>) wurde von <code>«atpVariation»</code> auf <code>«atpVariation,atpSplitable»</code> erweitert.\n</li></ul>"}, {"from": "FIG-be9824606273cce4", "to": "FIG-375235f3a51a0f49", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong><code>EcuInstance</code></strong>: Neues Attribut <code>channelSynchronousWakeup :Boolean [0..1]</code> ergänzt; Kardinalitäten von <code>sleepModeSupported</code> und <code>wakeUpOverBusSupported</code> von <code>1</code> (obligatorisch) auf <code>[0..1]</code> (optional) geändert.\n</li><li><strong><code>TpAddress</code></strong>: Kardinalität des Attributs <code>tpAddress</code> von <code>Integer</code> (1) auf <code>Integer [0..1]</code> geändert.\n</li><li><strong><code>J1939TpConnection</code></strong>: Kardinalität des Attributs <code>broadcast</code> von <code>Boolean</code> (1) auf <code>Boolean [0..1]</code> geändert.\n</li><li><strong><code>J1939TpConfig</code></strong>: Kardinalitäten der Aggregationen <code>+tpConnection</code>, <code>+tpNode</code> und <code>+tpAddress</code> von jeweils <code>1..*</code> auf <code>0..*</code> gelockert.\n</li><li><strong><code>J1939TpConnection</code></strong>: Kardinalität von <code>+dataPdu</code> von <code>1</code> auf <code>0..1</code> und von <code>+flowControlPdu</code> von <code>1..2</code> auf <code>0..2</code> gelockert.\n</li></ul>"}, {"from": "FIG-375235f3a51a0f49", "to": "FIG-adb7e688af117003", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong><code>J1939TpConnection</code></strong>: Neue Attribute <code>acceptVariableDA :Boolean [0..1]</code>, <code>acceptVariableSA :Boolean [0..1]</code>, <code>tpProtocolType :J1939TpProtocolTypeEnum [0..1]</code>, <code>useVariableDA :Boolean [0..1]</code> und <code>useVariableSA :Boolean [0..1]</code> ergänzt.\n</li></ul>"}, {"from": "FIG-adb7e688af117003", "to": "FIG-a02dcd2cef80aea1", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong><code>J1939TpConnection</code></strong>: Attribut <code>broadcast: Boolean [0..1]</code> wurde entfernt.\n</li><li><strong><code>J1939TpConnection</code></strong>: Attribute <code>bamTiming: TimeValue [0..1]</code> und <code>txPduPriority: PositiveInteger [0..1]</code> wurden hinzugefügt.\n</li><li><strong><code>J1939TpPg</code></strong>: Attribut <code>txDirectPduPriority: PositiveInteger [0..1]</code> wurde hinzugefügt.\n</li></ul>"}]};
